Object.assign(window.TEM8_DICTIONARY, {"keep":{"media":{"uk":"media/uk/keep__gb_1.mp3","us":"media/us/keep__us_1.mp3"},"oxford":{"phon":"kiːp","pos":"verb","senses":[{"en":"to continue to have something and not give it back or throw it away","cn":"保有；留着；不退还","g":"[transitive]","sc":"not give back","ex":{"en":"He kept all her letters.","cn":"他把她所有的信都保留着。"}},{"en":"to put or store something in a particular place","cn":"放，存放，贮存（在某处）","g":"[transitive]","sc":"put/store","ex":{"en":"Keep your passport in a safe place.","cn":"把你的护照放在安全的地方。"}},{"en":"to save something for somebody","cn":"（为某人）保留，留下","g":"[transitive]","lab":"especially British English","sc":"save for somebody","ex":{"en":"Please keep a seat for me.","cn":"请给我留个座位。"}},{"en":"to stay in a particular condition or position; to make somebody/something do this","cn":"（使）保持，处于","g":"[intransitive, transitive]","sc":"stay","ex":{"en":"We huddled together to keep warm.","cn":"我们挤在一起来保暖。"}},{"en":"to continue doing something; to do something repeatedly","cn":"继续，重复（做某事）","g":"[intransitive]","sc":"continue","ex":{"en":"Keep smiling!","cn":"要保持笑容！"}},{"en":"to know something and not tell it to anyone","cn":"保守（秘密）","g":"[transitive]","sc":"secret","ex":{"en":"Can you keep a secret?","cn":"你能保守秘密吗？"}},{"en":"to do what you have promised to do; to go where you have agreed to go","cn":"遵守；笃守；恪守","g":"[transitive]","sc":"promise/appointment","ex":{"en":"She kept her promise to visit them.","cn":"她遵守诺言去看望了他们。"}},{"en":"to write down something as a record","cn":"记下；记录；记载","g":"[transitive]","sc":"diary/record","ex":{"en":"She kept a diary for over twenty years.","cn":"她记了二十多年的日记。"}},{"en":"to own and care for animals","cn":"养；饲养","g":"[transitive]","sc":"animals","ex":{"en":"to keep bees/goats/hens","cn":"养蜜蜂／山羊／母鸡"}},{"en":"to own and manage a shop or restaurant","cn":"开，经营（商店或餐馆）","g":"[transitive]","lab":"especially British English","sc":"shop/restaurant","ex":{"en":"Her father kept a grocer's shop.","cn":"她父亲开了个杂货店。"}},{"en":"to provide what is necessary for somebody to live; to support somebody by paying for food, etc.","cn":"供养；养活","g":"[transitive]","sc":"support somebody","ex":{"en":"He scarcely earns enough to keep himself and his family.","cn":"他挣的钱几乎不够养活他自己和家人。"}},{"en":"to delay somebody","cn":"使耽搁；使延误","g":"[transitive]","sc":"delay","ex":{"en":"You're an hour late—what kept you?","cn":"你晚了一小时，什么事把你给耽误了？"}},{"en":"used to ask or talk about somebody’s health","cn":"（询问或谈论某人的健康）","g":"[intransitive]","lab":"informal","sc":"about health","ex":{"en":"How is your mother keeping?","cn":"你母亲身体好吗？"}},{"en":"to remain in good condition","cn":"保持不坏","g":"[intransitive]","lab":"informal, figurative，，","sc":"of food","ex":{"en":"Finish off the pie—it won't keep.","cn":"把馅饼都吃了吧，这东西不耐放。"}},{"en":"to protect somebody from something","cn":"保护；使免受","g":"[transitive]","lab":"formal","sc":"protect","ex":{"en":"May the Lord bless you and keep you (= used in prayers in the Christian Church).","cn":"愿上帝祝福你、保佑你（用于基督教的祈祷）。"}},{"en":"to guard or protect the goal or wicket","cn":"守门；把守球门","g":"[transitive]","sc":"in sport"},{"en":"food, clothes and all the other things that a person needs to live; the cost of these things","cn":"生活必需品；生活费用","g":"[uncountable]","ex":{"en":"It's about time you got a job to earn your keep.","cn":"你该找个工作挣自己的生活费了。"},"pos":"noun"},{"en":"a large strong tower, built as part of an old castle","cn":"城堡主楼","g":"[countable]","ex":{"en":"He made his way up a flight of steep stairs and into the main keep of the castle.","cn":"他爬上一段陡峭的楼梯，进入城堡的主楼。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-LINK-ERG连系动词（及物/不及物）","cn":"（使）保持","en":"If someone keeps or is kept in a particular state, they remain in it.","ex":{"en":"The noise kept him awake","cn":"噪音吵得他一直没有睡着。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）处于；（使）留在","en":"If you keep or you are kept in a particular position or place, you remain in it.","ex":{"en":"Keep away from the doors while the train is moving","cn":"列车运行过程中要远离车门。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）坚持（避免或不卷入）","en":"If you keep off something or keep away from it, you avoid it. If you keep out of something, you avoid getting involved in it. You can also say that you keep someone off ,away from or out of something.","ex":{"en":"I managed to stick to the diet and keep off sweet foods","cn":"我努力做到了只吃规定饮食，不沾甜食。"}},{"pos":"VERB 动词","cn":"阻止（或防止、阻碍）…做","en":"If someone or something keeps you from a particular action, they prevent you from doing it.","ex":{"en":"Embarrassment has kept me from doing all sorts of things","cn":"我总是害怕受窘，什么事都不敢去做。"}},{"pos":"VERB 动词","cn":"忍住（或克制）不做","en":"If you try to keep from doing something, you try to stop yourself from doing it.","ex":{"en":"She bit her lip to keep from crying","cn":"她咬住嘴唇不哭。"}},{"pos":"VERB 动词","cn":"保守;隐瞒","en":"If you keep something from someone, you do not tell them about it.","ex":{"en":"She knew that Gabriel was keeping something from her.","cn":"她知道加布里埃尔有事瞒着她。"}},{"pos":"VERB 动词","cn":"重复；继续","en":"If you keep doing something, you do it repeatedly or continue to do it.","ex":{"en":"I keep forgetting it's December","cn":"我总是忘了现在是12月了。"}},{"pos":"VERB 动词","cn":"（与某些名词连用，表示持续一段时间或继续做某事）持续，继续（持有或控制）","en":"Keep is used with some nouns to indicate that someone does something for a period of time or continues to do it. For example, if you keep a grip on something, you continue to hold or control it.","ex":{"en":"Until last year, the regime kept a tight grip on the country","cn":"直到去年，那个国家还处于该政权的严密控制之下。"}},{"pos":"VERB 动词","cn":"保留；保有；留有","en":"If you keep something, you continue to have it in your possession and do not throw it away, give it away, or sell it.","ex":{"en":"'I like this dress,' she said. 'Keep it. You can have it,' said Daphne","cn":"“我喜欢这件连衣裙，”她说。“留下吧。给你了，”达夫妮说道。"}},{"pos":"VERB 动词","cn":"存放；储存","en":"If you keep something in a particular place, you always have it or store it in that place so that you can use it whenever you need it.","ex":{"en":"She kept her money under the mattress","cn":"她把钱放在床垫下。"}},{"pos":"VERB 动词","cn":"遵守；笃守；恪守","en":"When you keep something such as a promise or an appointment, you do what you said you would do.","ex":{"en":"I'm hoping you'll keep your promise to come for a long visit","cn":"我希望你遵守诺言来这儿多呆几天。"}},{"pos":"VERB 动词","cn":"记下；记录；记载","en":"If you keep a record of a series of events, you write down details of it so that they can be referred to later.","ex":{"en":"Eleanor began to keep a diary","cn":"埃莉诺开始记日记了。"}},{"pos":"VERB 动词","cn":"供养；抚养；养活","en":"If you keep yourself or keep someone else, you support yourself or the other person by earning enough money to provide food, clothing, money, and other necessary things.","ex":{"en":"She could just about afford to keep her five kids","cn":"她勉勉强强能养得起自己的5个孩子。"}},{"pos":"N-SING 单数名词","cn":"生活费用","en":"Someone's keep is the cost of food and other things that they need in their daily life.","ex":{"en":"Ray will earn his keep on local farms while studying","cn":"雷求学期间会在当地的农场干活赚取生活费。"}},{"pos":"VERB 动词","cn":"饲养","en":"If you keep animals, you own them and take care of them.","ex":{"en":"I've brought you some eggs. We keep chickens","cn":"我给你带了些鸡蛋。我们养鸡。"}},{"pos":"VERB 动词","cn":"开设；经营；管理","en":"If you keep a business such as a small shop or hotel, you own it and manage it.","ex":{"en":"His father kept a village shop.","cn":"他父亲经营一家乡村商店。"}},{"pos":"VERB 动词","cn":"使耽搁;使延误","en":"If someone or something keeps you, they delay you and make you late.","ex":{"en":"Sorry to keep you, Jack","cn":"很抱歉让你久等了，杰克。"}},{"pos":"VERB 动词","cn":"（食物）保持不坏","en":"If food keeps for a certain length of time, it stays fresh and suitable to eat for that time.","ex":{"en":"Whatever is left over may be put into the refrigerator, where it will keep for 2-3 weeks.","cn":"剩下的东西都可以放进冰箱，可以保持两到三个星期不坏。"}},{"pos":"VERB 动词","cn":"（用于询问健康状况）保持健康","en":"You can say or ask how someone is keeping as a way of saying or asking whether they are well.","ex":{"en":"She hasn't been keeping too well lately","cn":"她最近身体不太好。"}},{"pos":"N-COUNT 可数名词","cn":"（中世纪的）城堡主楼","en":"A keep is the main tower of a medieval castle, in which people lived."},{"pos":"PHRASE 短语","cn":"继续做；坚持干","en":"If you keep at it, you continue doing something that you have started, even if you are tired and would prefer to stop.","ex":{"en":"It may take a number of attempts, but it is worth keeping at it","cn":"可能要试几次，但还是值得坚持的。"}},{"pos":"PHRASE 短语","cn":"永远；永不更改地","en":"Something that is for keeps is permanent and will not change.","ex":{"en":"Ensure that whatever you gain now will be for keeps","cn":"确保你现在所获得的一切永远不会失去。"}},{"pos":"PHRASE 短语","cn":"继续移动;坚持干","en":"If you keep going, you continue moving along or doing something that you have started, even if you are tired and would prefer to stop.","ex":{"en":"She forced herself to keep going","cn":"她强迫自己继续下去。"}},{"pos":"PHRASE 短语","cn":"协调/不协调;一致/不一致","en":"If one thing is in keeping with another, it is suitable in relation to that thing. If one thing is out of keeping with another, it is not suitable in relation to that thing.","ex":{"en":"His office was in keeping with his station and experience","cn":"他的办公室与其身份和阅历相称。"}},{"pos":"PHRASE 短语","cn":"继续努力","en":"If you keep it up, you continue working or trying as hard as you have been in the past.","ex":{"en":"There are fears that he will not be able to keep it up when he gets to the particularly demanding third year","cn":"有人担心他到了要求极其严格的第3年时会坚持不下去。"}},{"pos":"PHRASE 短语","cn":"把…秘而不宣；不将…说出去","en":"If you keep something to yourself, you do not tell anyone else about it.","ex":{"en":"I have to tell someone. I can't keep it to myself","cn":"我得找人说说。我心里憋不住。"}},{"pos":"PHRASE 短语","cn":"离群索居；不与人来往","en":"If you keep yourself to yourself or keep to yourself, you stay on your own most of the time and do not mix socially with other people.","ex":{"en":"He was a quiet man who kept himself to himself","cn":"他是个喜欢安静、不爱与人来往的人。"}},{"pos":"","cn":"","en":"to keep someone company→see: ; to keep your end up→see: ; to keep a straight face→see: ; to keep your hand in→see: ; to keep your head→see: ; to keep house→see: ; to keep pace→see: ; to keep the peace→see: ; to keep a secret→see: ; to keep time→see: ; to keep track→see: ;"},{"pos":"","cn":"","en":"相关词组：keep back keep down keep in with keep on keep on about keep on at keep to keep up"}]},"examples":[{"en":"( informal, figurative ) ‘I'd love to hear about it, but I'm late already.’ ‘That's OK — it'll keep (= I can tell you about it later). ’ “","cn":"我很想听听，不过我已经迟到了。” “好吧，我以后再告诉你。”"},{"en":"May the Lord bless you and keep you (= used in prayers in the Christian Church).","cn":"愿上帝祝福你、保佑你（用于基督教的祈祷）。"}]},"kilogram":{"oxford":{"phon":"ˈkɪləɡræm","pos":"noun","senses":[{"en":"a unit for measuring weight; 1 000 grams","cn":"千克；公斤","ex":{"en":"2 kilograms of rice","cn":"2 公斤大米"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"千克；公斤","en":"A kilogram is a metric unit of weight. One kilogram is a thousand grams, or a thousandth of a metric ton, and is equal to 2.2 pounds.","ex":{"en":"...a parcel weighing around 4.5 kilograms.","cn":"重约4.5千克的包裹"}}]},"media":{"uk":"media/uk/kilogram__gb_1.mp3","us":"media/us/kilogram__us_1.mp3"},"examples":[{"en":"Flour is sold by the kilogram.","cn":"面粉按公斤出售。"},{"en":"2 kilograms of rice * 2","cn":"公斤大米"}]},"kidneys":{"lemma":"kidney","media":{"uk":"media/uk/kidney__gb_1.mp3","us":"media/us/kidney__us_1.mp3"}},"kitchenette":{"oxford":{"phon":"ˌkɪtʃɪˈnet","pos":"noun","senses":[{"en":"a small room or part of a room used as a kitchen, for example in a flat","cn":"小厨房；套房里的厨房区"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小厨房；房间里用作厨房的一角","en":"A kitchenette is a small kitchen, or a part of a larger room that is used for cooking."}]},"media":{"uk":"media/uk/kitchenette__gb_1.mp3","us":"media/us/kitchenette__us_1.mp3"}},"known":{"media":{"uk":"media/uk/known__gb_2.mp3","us":"media/us/known__us_2.mp3"},"oxford":{"phon":"nəʊn","pos":"adjective","senses":[{"en":"known about, especially by a lot of people","cn":"知名的；出了名的；已知的","ex":{"en":"He's a known thief.","cn":"他是个出了名的小偷。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Known is the past participle of know ."},{"pos":"ADJ 形容词","cn":"知名的；出了名的；已知的","en":"You use known to describe someone or something that is clearly recognized by or familiar to all people or to a particular group of people.","ex":{"en":"...He was a known drug dealer","cn":"他是个臭名昭著的毒贩子。"}},{"pos":"ADJ 形容词","cn":"以…闻名的","en":"If someone or something is known for a particular achievement or feature, they are familiar to many people because of that achievement or feature.","ex":{"en":"He is better known for his film and TV work.","cn":"他的影视作品更为出名。"}},{"pos":"PHRASE 短语","cn":"使人们知道（或清楚）；明确表示","en":"If you let it be known that something is the case, or you let something be known, you make sure that people know it or can find out about it.","ex":{"en":"The Prime Minister has let it be known that he is against it","cn":"首相对此明确表示反对。"}}]},"examples":[{"en":"The disease has no known cure.","cn":"这种病目前还是不治之症。"},{"en":"He's a known thief.","cn":"他是个出了名的小偷。"}],"base":"know"},"knew":{"lemma":"know","media":{"uk":"media/uk/knew__gb_1.mp3","us":"media/us/knew__us_1.mp3"}},"kilometre":{"media":{"uk":"media/uk/kilometre__gb_1.mp3","us":"media/us/kilometre__us_1.mp3"},"oxford":{"phon":"kɪˈlɒmɪtə(r)","pos":"noun","senses":[{"en":"a unit for measuring distance; 1 000 metres","cn":"千米；公里","ex":{"en":"The industrial estate is 6 kilometres from the city centre.","cn":"工业园区距离市中心 6 公里。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"千米；公里","en":"A kilometre is a metric unit of distance or length. One kilometre is a thousand metres and is equal to 0.62 miles.","ex":{"en":"...about twenty kilometres from the border","cn":"离边界约20公里"}}]}},"kj":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"kilojoule","cn":"千焦（耳）"}]}},"kindred":{"media":{"uk":"media/uk/kindred__gb_1.mp3","us":"media/us/kindred__us_1.mp3"},"oxford":{"phon":"ˈkɪndrəd","pos":"noun","senses":[{"en":"your family and relatives","cn":"（统称）家人，亲属","g":"[plural]"},{"en":"the fact of being related to another person","cn":"亲属关系；血缘关系","g":"[uncountable]","ex":{"en":"ties of kindred","cn":"亲属关系"}},{"en":"very similar; related","cn":"类似的；相似的；相关的；有血缘关系的","ex":{"en":"food and kindred products","cn":"食物及类似产品"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（统称）家人，亲属","en":"Your kindred are your family, and all the people who are related to you.","ex":{"en":"The offender made proper restitution to the victim's kindred.","cn":"违法者对受害人亲属给予了适当的补偿。"}},{"pos":"ADJ 形容词","cn":"类似的；相似的","en":"Kindred things are similar to each other.","ex":{"en":"I recall many discussions with her on these and kindred topics.","cn":"我回想起多次同她就这些问题及类似话题进行的讨论。"}}]},"examples":[{"en":"I knew I'd found a kindred spirit (= a person with similar ideas, opinions, etc.).","cn":"我知道我找到了志同道合的人。"},{"en":"food and kindred products","cn":"食物及类似产品"}]},"know":{"media":{"uk":"media/uk/know__gb_1.mp3","us":"media/us/know__us_1.mp3"},"oxford":{"phon":"nəʊ","pos":"verb","senses":[{"en":"to have information in your mind as a result of experience or because you have learned or been told it","cn":"知道；知悉；了解","g":"[transitive, intransitive]","lab":"informal","sc":"have information","ex":{"en":"No one knows the answer.","cn":"没有人知道答案。"}},{"en":"to realize, understand or be aware of something","cn":"认识到；懂得；意识到","g":"[transitive, intransitive]","sc":"realize","ex":{"en":"As soon as I walked in the room I knew (that) something was wrong.","cn":"我刚走进屋就意识到出了事。"}},{"en":"to feel certain about something","cn":"确信；确知；肯定","g":"[transitive, intransitive]","sc":"feel certain","ex":{"en":"He knew (that) he could trust her.","cn":"他确信她是可以信赖的。"}},{"en":"to be familiar with a person, place, thing, etc.","cn":"熟悉；认识；了解","g":"[transitive]","sc":"be familiar","ex":{"en":"I've known David for 20 years.","cn":"我认识戴维已有 20 年了。"}},{"en":"to have learned a skill or language and be able to use it","cn":"学会；掌握","g":"[transitive]","sc":"skill/language","ex":{"en":"Do you know any Japanese?","cn":"你会日语吗？"}},{"en":"to think that somebody/something is a particular type of person or thing or has particular characteristics","cn":"把…看作是；认为…是","g":"[transitive, usually passive]","sc":"reputation","ex":{"en":"He has become widely known as an expert in child psychology.","cn":"他作为儿童心理学专家，已经广为人知。"}},{"en":"to give somebody/something a particular name or title","cn":"将…称为；把…叫作","g":"[transitive]","sc":"give name","ex":{"en":"Iran was formerly known as Persia.","cn":"伊朗旧称波斯。"}},{"en":"to be able to recognize somebody/something","cn":"能认出；能辨认出","g":"[transitive]","sc":"recognize","ex":{"en":"I couldn't see who was speaking, but I knew the voice.","cn":"我看不到是谁在讲话，但我能辨认出声音。"}},{"en":"to understand the difference between one person or thing and another","cn":"分辨；辨别","g":"[transitive]","sc":"understand the difference","ex":{"en":"I hope we have taught our children to know right from wrong.","cn":"我希望我们教给了孩子分辨是非的能力。"}},{"en":"to have seen, heard or experienced something","cn":"看到过；听到过；经历过","g":"[transitive]","sc":"experience","ex":{"en":"I’ve never known it (to) snow in July before.","cn":"我以前从未见到过七月份下雪。"}},{"en":"to have personal experience of something","cn":"亲身体验；亲身经历","g":"[transitive]","sc":"experience","ex":{"en":"He has known both poverty and wealth.","cn":"他贫富生活都亲身经历过。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"知道；知悉；了解","en":"If you know a fact, a piece of information, or an answer, you have it correctly in your mind.","ex":{"en":"I don't know the name of the place","cn":"我不知道那个地方的名字。"}},{"pos":"VERB 动词","cn":"熟识；认识","en":"If you know someone, you are familiar with them because you have met them and talked to them before.","ex":{"en":"Gifford was a friend. I'd known him for nine years","cn":"吉福德是我的一位朋友。我和他认识9年了。"}},{"pos":"VERB 动词","cn":"听说过；略有耳闻","en":"If you say that you know of something, you mean that you have heard about it but you do not necessarily have a lot of information about it.","ex":{"en":"We know of the incident but have no further details","cn":"我们听说过这件事，但对详情不是很清楚。"}},{"pos":"VERB 动词","cn":"了解，掌握（某一学科）","en":"If you know about a subject, you have studied it or taken an interest in it, and understand part or all of it.","ex":{"en":"Hire someone with experience, someone who knows about real estate","cn":"雇佣有经验、了解房地产业的人。"}},{"pos":"VERB 动词","cn":"学会，掌握（语言）","en":"If you know a language, you have learned it and can understand it.","ex":{"en":"It helps to know French and Creole if you want to understand some of the lyrics","cn":"如果你想读懂一些抒情诗，学点法语和克里奥尔语是有帮助的。"}},{"pos":"VERB 动词","cn":"熟悉；了解","en":"If you know something such as a place, a work of art, or an idea, you have visited it, seen it, read it, or heard about it, and so you are familiar with it.","ex":{"en":"No matter how well you know Paris, it is easy to get lost","cn":"不管你对巴黎多么熟悉，也很容易迷路。"}},{"pos":"VERB 动词","cn":"会；能","en":"If you know how to do something, you have the necessary skills and knowledge to do it.","ex":{"en":"The health authorities now know how to deal with the disease","cn":"卫生部门现在知道如何对付这种病了。"}},{"pos":"VERB 动词","cn":"意识到；觉察到","en":"You can say that someone knows that something is happening when they become aware of it.","ex":{"en":"Then I saw a gun under the hall table so I knew that something was wrong","cn":"后来我看到大厅的桌子下有一把枪，我就意识到有些不对劲儿。"}},{"pos":"VERB 动词","cn":"认出；辨认出","en":"If you know something or someone, you recognize them when you see them or hear them.","ex":{"en":"Would she know you if she saw you on the street?","cn":"如果她在大街上看到你，能认出你吗？"}},{"pos":"VERB 动词","cn":"称为；叫做","en":"If someone or something is known as a particular name, they are called by that name.","ex":{"en":"The disease is more commonly known as Mad Cow Disease","cn":"这种疾病更通俗的名称是疯牛病。"}},{"pos":"VERB 动词","cn":"认为…是；把…看作是","en":"If you know someone or something as a person or thing that has particular qualities, you consider that they have those qualities.","ex":{"en":"Lots of people know her as a very kind woman","cn":"很多人认为她是个非常善良的女人。"}},{"pos":"VERB 动词","cn":"（因某工作或角色）认识","en":"If you know someone as a person with a particular job or role, you are familiar with them in that job or role, rather than in any other.","ex":{"en":"Most of us know her as the woman who used to present the television news","cn":"我们大多数人认识她是因为她曾主持过电视新闻节目。"}},{"pos":"PHRASE 短语","cn":"现行的；我们熟悉的；我们熟知的","en":"If you talk about a thing or system as we know it, you are referring to the form in which it exists now and which is familiar to most people.","ex":{"en":"He planned to end the welfare system as we know it.","cn":"他计划终止现行的福利制度。"}},{"pos":"PHRASE 短语","cn":"（花时间）了解","en":"If you get to know someone, you find out what they are like by spending time with them.","ex":{"en":"The new neighbours were getting to know each other","cn":"新邻居之间正在互相了解。"}},{"pos":"PHRASE 短语","cn":"谁知道；天晓得","en":"People use expressions such as goodness knows ,Heaven knows, and God knows when they do not know something and want to suggest that nobody could possibly know it.","ex":{"en":"'Who's he?' — 'God knows.'","cn":"“他是谁？”——“天晓得。”"}},{"pos":"CONVENTION 惯用语","cn":"（表示同意）我理解，我有同感，我知道","en":"You say 'I know' to show that you agree with what has just been said.","ex":{"en":"'This country is so awful.' — 'I know, I know.'","cn":"“这个国家太糟糕了。”——“的确是，的确是。”"}},{"pos":"CONVENTION 惯用语","cn":"（表示接受）我知道","en":"You say 'I know' to show that you accept that something is true, but think that it is not very important or relevant.","ex":{"en":"'There are trains straight from Cambridge.' — 'I know, but it's no quicker.'","cn":"“有直接从剑桥开出的列车。”——“我知道，但也不快。”"}},{"pos":"PHRASE 短语","cn":"（表示同情和理解）我理解，我知道","en":"You use 'I know' to express sympathy and understanding towards someone.","ex":{"en":"I'm sorry, George. I know how you feel","cn":"我很遗憾，乔治。我理解你的感受。"}},{"pos":"PHRASE 短语","cn":"不知道，不认为（表示不完全同意或不认为是真的）","en":"You can use I don't know to indicate that you do not completely agree with something or do not really think that it is true.","ex":{"en":"'He should quite simply resign.' — 'I don't know about that.'","cn":"“他就该辞职。”——“我不知道。”"}},{"pos":"PHRASE 短语","cn":"我不知道你（们）怎么想（表示将表达自己想法并想知道他人的看法）","en":"You can say 'I don't know about you' to indicate that you are going to give your own opinion about something and you want to find out if someone else feels the same.","ex":{"en":"I don't know about the rest of you, but I'm hungry","cn":"我不知道你们怎么样，但我是饿了。"}},{"pos":"PHRASE 短语","cn":"（表示批评某人的行为）真想不到，真不知道","en":"You use I don't know in expressions which indicate criticism of someone's behaviour. For example, if you say that you do not know how someone can do something, you mean that you cannot understand or accept them doing it.","ex":{"en":"I don't know how he could do this to his own daughter","cn":"真想不到他竟对自己的女儿这样。"}},{"pos":"PHRASE 短语","cn":"我要是知道就好了；我根本不知道","en":"People sometimes use expressions such as I'm blessed if I know or damned if I know to emphasize the fact that they do not know something.","ex":{"en":"'What was that all about?' — 'Damned if I know.'","cn":"“那都是关于什么的？”——“我要知道就好了。”"}},{"pos":"PHRASE 短语","cn":"知情；（尤指）熟悉内幕，掌握内情","en":"If you are in the know about something, especially something that is not known about or understood by many people, you have information about it.","ex":{"en":"It was gratifying to be in the know about important people","cn":"了解重要人物的一些内幕真令人高兴。"}},{"pos":"CONVENTION 惯用语","cn":"（表示所说的话对方理解）你是知道的，你知道我的意思","en":"You can use expressions such as you know what I mean and if you know what I mean to suggest that the person listening to you understands what you are trying to say, and so you do not have to explain any more.","ex":{"en":"None of us stayed long. I mean, the atmosphere wasn't — well, you know what I mean","cn":"我们都没呆太久。我的意思是，气氛并不是——唔，你知道我的意思。"}},{"pos":"CONVENTION 惯用语","cn":"（指可能会发生好事）很难说，很难预料","en":"You say 'You never know' or 'One never knows' to indicate that it is not definite or certain what will happen in the future, and to suggest that there is some hope that things will turn out well.","ex":{"en":"You never know, I might get lucky","cn":"很难说，我也许会交好运呢。"}},{"pos":"CONVENTION 惯用语","cn":"据我所知没有","en":"You say 'Not that I know of' when someone has asked you whether or not something is true and you think the answer is 'no' but you cannot be sure because you do not know all the facts.","ex":{"en":"'Is he married?' — 'Not that I know of.'","cn":"“他结婚了吗？”——“据我所知没有。”"}},{"pos":"PHRASE 短语","cn":"我怎么知道；我不知道","en":"You can say 'How was I to know?', or in British English 'I wasn't to know', to mean that you cannot be blamed or criticized for something you did, because you did not have enough information to realize that it was wrong.","ex":{"en":"How was I to know you'd return so suddenly?","cn":"我怎么知道你会这么突然就回来?"}},{"pos":"PHRASE 短语","cn":"（某人）知道什么，懂什么（表示其没有资格评论）","en":"You can use expressions such as What does she know? and What do they know? when you think that someone has no right to comment on a situation because they do not understand it.","ex":{"en":"Don't listen to him, what does he know?","cn":"别听他的，他知道什么？"}},{"pos":"EXCLAM 感叹语","cn":"（表示惊讶）你看怪不怪，真没想到","en":"People sometimes say 'What do you know!' when they are very surprised about something.","ex":{"en":"Well, what do you know!","cn":"哎呀，真没想到！"}},{"pos":"CONVENTION 惯用语","cn":"（加强语气或引起注意）你要知道","en":"You use you know to emphasize or to draw attention to what you are saying.","ex":{"en":"The conditions in there are awful, you know","cn":"你要知道，那里的条件很艰苦。"}},{"pos":"CONVENTION 惯用语","cn":"（表示不确定要说的话或考虑接着说什么）你知道","en":"People use you know when they are uncertain about what they are saying or what they are going to say next.","ex":{"en":"He's generous and, you know, very nice, very polite","cn":"他很大方而且，你知道，很友善，很有礼貌。"}},{"pos":"CONVENTION 惯用语","cn":"（表示进一步解释）你是知道的，你难道不知道","en":"You use you know when you are trying to explain more clearly what you mean, by referring to something that the person you are talking to knows about.","ex":{"en":"Wear the white dress, you know, the one with all the black embroidery.","cn":"穿那件白裙，你知道的，上面有黑色刺绣的那件。"}},{"pos":"PHRASE 短语","cn":"（加强语气）你不知道，你都想不到","en":"You can say 'You don't know' in order to emphasize how strongly you feel about the remark you are going to make.","ex":{"en":"You don't know how good it is to speak to somebody from home.","cn":"你不知道和家乡来的人说说话感觉有多好。"}},{"pos":"","cn":"","en":"to know something backwards→see: ; to know best→see: ; to know better→see: ; to know no bounds→see: ; to know what side your bread is buttered on→see: ; to know something for a fact→see: ; as far as I know→see: ; not to know the first thing about something→see: ; to know full well→see: ; to let someone know→see: ; not to know the meaning of the word→see: ; to know your own mind→see: ; for reasons best known to oneself→see: ; to know the ropes→see: ;"}]},"examples":[{"en":"‘I'm sorry, I called when you were in bed.’ ‘Don't worry — you weren't to know.’ “","cn":"对不起，你睡觉时打电话打扰你了。” “别在意，你不是故意的嘛。”"},{"en":"We were whisked off in a taxi before we knew where we were.","cn":"还没等我们弄清怎么回事，出租车就一阵风似地把我们带走了。"}]},"kernel":{"oxford":{"phon":"ˈkɜːnl","pos":"noun","senses":[{"en":"the inner part of a nut or seed","cn":"（坚果或籽粒的）仁，核","ex":{"en":"pine/apricot kernels","cn":"松仁；杏仁"}},{"en":"the central, most important part of an idea or a subject","cn":"（思想或主题的）核心，中心，要点","ex":{"en":"the kernel of her argument","cn":"她的论据的核心。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（坚果的）仁，核","en":"The kernel of a nut is the part that is inside the shell."},{"pos":"N-COUNT 可数名词","cn":"核心；中心；要点","en":"The kernel of something is the central and most important part of it.","ex":{"en":"The kernel of that message was that peace must not be a source of advantage or disadvantage for anyone.","cn":"那一信息的核心是和平绝不应该成为对任何人有利或不利的根源。"}},{"pos":"N-COUNT 可数名词","cn":"一小部分","en":"A kernel of something is a small element of it.","ex":{"en":"For all I know, there may be a kernel of truth in what he says.","cn":"据我所知，他的话可能有一点儿道理。"}}]},"media":{"uk":"media/uk/kernel__gb_1.mp3","us":"media/us/kernel__us_1.mp3"},"examples":[{"en":"This evidence is the kernel of the defendants’ case.","cn":"这项证据是被告辩护中的关键点。"},{"en":"There may be a kernel of truth in what he says.","cn":"他说的话也可能有点真实的成分。"}]},"knocking":{"lemma":"knock","media":{"uk":"media/uk/knock__gb_1.mp3","us":"media/us/knock__us_1.mp3"}},"kennel":{"media":{"uk":"media/uk/kennel__gb_1.mp3","us":"media/us/kennel__us_1.mp3"},"oxford":{"phon":"ˈkenl","pos":"noun","senses":[{"en":"a small shelter for a dog to sleep in","cn":"狗窝；犬舍","lab":"North American English"},{"en":"a place where people can leave their dogs to be taken care of when they go on holiday; a place where dogs are kept in order to produce young","cn":"狗寄养所；狗繁殖场","g":"[countable + singular or plural verb]","ex":{"en":"We put the dog in kennels when we go away.","cn":"我们外出时把狗送到寄养所。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"狗窝；犬舍","en":"A kennel is a small building made especially for a dog to sleep in."},{"pos":"N-COUNT 可数名词","cn":"（驯养或寄养狗的）养狗场","en":"Kennels or a kennels or a kennel is a place where dogs are bred and trained, or looked after when their owners are away.","ex":{"en":"The guard dog was now in kennels as it was not aggressive","cn":"这条看门狗不好斗，因此正在养狗场受训。"}}]},"examples":[{"en":"We put the dog in kennels when we go away.","cn":"我们外出时把狗寄养在养狗场。"},{"en":"The puppy, which may have rabies, is at a quarantine kennel.","cn":"这只幼犬可能得了狂犬病﹐被关在隔离站。"}]},"knowing":{"media":{"uk":"media/uk/knowing__gb_1.mp3","us":"media/us/knowing__us_1.mp3"},"oxford":{"phon":"ˈnəʊɪŋ","pos":"adjective","senses":[{"en":"showing that you know or understand about something that is supposed to be secret","cn":"会意的；心照不宣的；知情的","ex":{"en":"a knowing smile","cn":"会意的微笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"会意的；心照不宣的；知情的","en":"A knowing gesture or remark is one that shows that you understand something, for example the way that someone is feeling or what they really mean, even though it has not been mentioned directly.","ex":{"en":"Ron gave her a knowing smile","cn":"罗恩朝她会意地一笑。"}}]},"examples":[{"en":"a knowing smile","cn":"会意的微笑"},{"en":"He gave us a knowing look .","cn":"他朝我们会意地看了一眼。"}],"base":"know"},"knitting":{"oxford":{"phon":"ˈnɪtɪŋ","pos":"noun","senses":[{"en":"an item that is being knitted","cn":"编织物；针织品","ex":{"en":"Where's my knitting?","cn":"我织的东西上哪儿去了？"}},{"en":"the activity of knitting","cn":"编织；针织"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"编织物；针织品","en":"Knitting is something, such as an article of clothing, that is being knitted.","ex":{"en":"She had been sitting with her knitting at her fourth-floor window.","cn":"她那时正坐在5楼的窗前织东西。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"编织；针织","en":"Knitting is the action or process of knitting.","ex":{"en":"Take up a relaxing hobby, such as knitting.","cn":"培养一种能放松身心的爱好，比如编织。"}}]},"media":{"img":["media/pic/knitting_comp.jpg","media/thumb/knitting.jpg"],"uk":"media/uk/knitting__gb_1.mp3","us":"media/us/knitting__us_1.mp3"},"examples":[{"en":"Where's my knitting?","cn":"我织的东西上哪儿去了？"}]},"knob":{"oxford":{"phon":"nɒb","pos":"noun","senses":[{"en":"a round switch on a machine such as a radio that you use to turn it on and off, etc.","cn":"（控制机器开关等的）旋钮","ex":{"en":"the volume control knob","cn":"音量控制旋钮"}},{"en":"a round handle on a door or a drawer","cn":"（门或抽屉的）球形拉手","ex":{"en":"I tried the knob, and this time the door opened.","cn":"我试着旋动球形把手，这次门开了。"}},{"en":"a round shape like a ball on the surface or end of something","cn":"疙瘩；节","ex":{"en":"He carried a long cane, tipped with an iron knob.","cn":"他拿着一根长手杖，手杖的顶端有一个铁把手。"}},{"en":"a small piece of something such as butter","cn":"（黄油等的）小块，坨","lab":"especially British English"},{"en":"a penis","cn":"鸡巴；屌","lab":"British English, taboo, slang，，，，"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（门或抽屉的）球形把手","en":"A knob is a round handle on a door or drawer which you use in order to open or close it.","ex":{"en":"He turned the knob and pushed against the door.","cn":"他扭动把手推了推门。"}},{"pos":"N-COUNT 可数名词","cn":"（柱子或棍子顶部的）疙瘩，节，球状物","en":"A knob is a rounded lump or ball on top of a post or stick.","ex":{"en":"A loose brass knob on the bedstead rattled.","cn":"床架上一个松动的球形铜扣发出嘎啦声。"}},{"pos":"N-COUNT 可数名词","cn":"（机器或设备的）旋钮","en":"A knob is a round switch on a piece of machinery or equipment.","ex":{"en":"...the volume knob.","cn":"音量旋钮"}},{"pos":"N-COUNT 可数名词","cn":"小块（黄油）","en":"A knob of butter is a small amount of it.","ex":{"en":"Top the steaming hot potatoes with a knob of butter.","cn":"在冒热气的马铃薯上放一小块黄油。"}}]},"media":{"img":["media/pic/handle_comp.jpg","media/thumb/knob.jpg"],"uk":"media/uk/knob__gb_1.mp3","us":"media/us/knob__us_1.mp3"},"examples":[{"en":"It isn't art — it's just a horror movie with knobs on!","cn":"那不是艺术，只是更加惊悚的恐怖片而已！"},{"en":"the volume control knob","cn":"音量控制旋钮"}]},"kingdoms":{"lemma":"kingdom"},"keyboard":{"oxford":{"phon":"ˈkiːbɔːd","pos":"noun","senses":[{"en":"the set of keys for operating a computer or typewriter, or the set of letters that you can touch to write on a smartphone or tablet","cn":"（计算机或打字机的）键盘；（智能手机或平板电脑的）虚拟键盘","ex":{"en":"The program locks the keyboard until a password is given.","cn":"这个程序锁住了键盘，需要输入密码。"}},{"en":"the set of black and white keys on a piano or other musical instrument","cn":"（钢琴或其他乐器的）琴键，键盘","ex":{"en":"a piano keyboard","cn":"钢琴键盘"}},{"en":"an electronic musical instrument that has keys like a piano and can be made to play in different styles or to sound like different instruments","cn":"键盘式电子乐器","ex":{"en":"She plays keyboard and guitar.","cn":"她弹键盘和吉他。"}},{"en":"to type information into a computer","cn":"用键盘输入；将（信息）键入计算机","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（打字机或计算机的）键盘","en":"The keyboard of a typewriter or computer is the set of keys that you press in order to operate it."},{"pos":"N-COUNT 可数名词","cn":"（钢琴或风琴的）琴键，键盘","en":"The keyboard of a piano or organ is the set of black and white keys that you press in order to play it.","ex":{"en":"Tanya's hands rippled over the keyboard.","cn":"塔尼娅的双手在琴键上翻飞。"}},{"pos":"N-COUNT 可数名词","cn":"键盘乐器","en":"People sometimes refer to musical instruments that have a keyboard as keyboards .","ex":{"en":"...Sean O'Hagan on keyboards.","cn":"键盘手肖恩·奥黑根"}}]},"media":{"uk":"media/uk/keyboard__gb_1.mp3","us":"media/us/keyboard__us_1.mp3"},"examples":[{"en":"Chris Kelly (guitar) and Benny Hayes (keyboards and vocals)","cn":"克里斯·凯利(吉他手)和本尼·海斯(键盘手和主唱)"},{"en":"a computer keyboard","cn":"计算机键盘"}]},"kindness":{"media":{"uk":"media/uk/kindness__gb_1.mp3","us":"media/us/kindness__us_1.mp3"},"oxford":{"phon":"ˈkaɪndnəs","pos":"noun","senses":[{"en":"the quality of being kind","cn":"仁慈；善良；体贴；宽容","g":"[uncountable]","ex":{"en":"to treat somebody with kindness and consideration","cn":"待人体贴周到"}},{"en":"a kind act","cn":"友好（或仁慈、体贴）的举动","g":"[countable]","ex":{"en":"I can never repay your many kindnesses to me.","cn":"我永远无法报答你对我无微不至的关怀。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"仁慈；体贴；友好","en":"Kindness is the quality of being gentle, caring, and helpful.","ex":{"en":"We have been treated with such kindness by everybody.","cn":"每个人对我们都很好。"}},{"pos":"N-COUNT 可数名词","cn":"友好（或体贴）的举动","en":"A kindness is a helpful or considerate act."}]},"examples":[{"en":"I can never repay your many kindnesses to me.","cn":"我无法报答你对我无微不至的关怀。"},{"en":"to treat sb with kindness and consideration","cn":"待人体贴周到"}]},"kp":{"oxford":{"phon":"ˌkeɪ ˈpiː","pos":"noun","senses":[{"en":"work done by soldiers in the kitchen, usually as a punishment","cn":"（通常作为士兵惩罚的）伙房帮厨","ex":{"en":"The sergeant assigned him to KP.","cn":"中士派他下伙房去帮厨。"}}]},"media":{"uk":"media/uk/kp__gb_1.mp3","us":"media/us/kp__us_1.mp3"},"examples":[{"en":"The sergeant assigned him to KP.","cn":"中士派他下伙房去帮厨。"}]},"keeping":{"lemma":"keep","media":{"uk":"media/uk/keeping__gb_1.mp3","us":"media/us/keeping__us_1.mp3"}},"kitchen":{"media":{"img":["media/pic/kitchen_objects_comp.jpg","media/thumb/kitchen.jpg"],"uk":"media/uk/kitchen__gb_1.mp3","us":"media/us/kitchen__us_1.mp3"},"oxford":{"phon":"ˈkɪtʃɪn","pos":"noun","senses":[{"en":"a room in which meals are cooked or prepared","cn":"厨房","lab":"especially British English","ex":{"en":"We ate at the kitchen table.","cn":"我们在厨房里的桌子上吃饭。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"厨房","en":"A kitchen is a room that is used for cooking and for household jobs such as washing dishes."}]},"examples":[{"en":"We ate at the kitchen table.","cn":"我们在厨房里的桌子上吃饭。"},{"en":"She's in the kitchen.","cn":"她在厨房里。"}]},"knowledgeable":{"media":{"uk":"media/uk/knowledgeable__gb_1.mp3","us":"media/us/knowledgeable__us_1.mp3"},"oxford":{"phon":"ˈnɒlɪdʒəbl","pos":"adjective","senses":[{"en":"knowing a lot","cn":"博学的；有见识的；知识渊博的","ex":{"en":"She is very knowledgeable about plants.","cn":"她对植物很在行。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"博学的；有见识的；知识渊博的","en":"Someone who is knowledgeable has or shows a clear understanding of many different facts about the world or about a particular subject.","ex":{"en":"We employ friendly and knowledgeable staff.","cn":"我们雇佣友善的、在行的员工。"}}]},"examples":[{"en":"She is very knowledgeable about plants.","cn":"她对植物很在行。"},{"en":"Graham’s very knowledgeable about wines.","cn":"格雷厄姆对葡萄酒很在行。"}]},"kicking":{"media":{"uk":"media/uk/kicking__gb_1.mp3","us":"media/us/kicking__us_1.mp3"},"oxford":{"phon":"ˈkɪkɪŋ","pos":"adjective","senses":[{"en":"full of life and excitement","cn":"充满活力的；充满刺激的；令人兴奋的","ex":{"en":"The club was really kicking last night.","cn":"昨晚俱乐部真是热闹非凡。"}},{"en":"an act of kicking somebody hard and repeatedly, especially when they are lying on the ground","cn":"（尤指对躺在地上的人连续的）狠踢，猛踹","ex":{"en":"They gave him a good kicking.","cn":"他们狠狠地踢了他一顿。"},"pos":"noun"}]},"examples":[{"en":"The club was really kicking last night.","cn":"昨晚俱乐部真是热闹非凡。"},{"en":"They gave him a good kicking.","cn":"他们狠狠地踢了他一顿。"}],"base":"kick"},"kept":{"lemma":"keep","media":{"uk":"media/uk/kept__gb_1.mp3","us":"media/us/kept__us_1.mp3"}},"king":{"media":{"uk":"media/uk/king__gb_1.mp3","us":"media/us/king__us_1.mp3"},"oxford":{"phon":"kɪŋ","pos":"noun","senses":[{"en":"the male ruler of an independent state that has a royal family","cn":"君主；国王","ex":{"en":"the kings and queens of England","cn":"英格兰国王和女王"}},{"en":"a person, an animal or a thing that is thought to be the best or most important of a particular type","cn":"（人、动物、事物中的）首屈一指者，最重要者，大王","ex":{"en":"the king of comedy","cn":"喜剧之王"}},{"en":"used in compounds with the names of animals or plants to describe a very large type of the thing mentioned","cn":"（与动植物名称连用构成复合词，表示巨型）…之最，…之王，巨型…","ex":{"en":"a king penguin","cn":"王企鹅"}},{"en":"the most important piece used in the game of chess, that can move one square in any direction","cn":"（国际象棋中的）王"},{"en":"a playing card with the picture of a king on it","cn":"（纸牌中的）老 K"}]},"collins":{"senses":[{"pos":"N-TITLE; N-COUNT 头衔名词；可数名词","cn":"君主；国王","en":"A king is a man who is the most important member of the royal family of his country, and who is considered to be the Head of State of that country.","ex":{"en":"...the king and queen of Spain","cn":"西班牙国王和王后"}},{"pos":"N-COUNT 可数名词","cn":"最重要者；首屈一指者；…之王","en":"If you describe a man as the king of something, you mean that he is the most important person doing that thing or he is the best at doing it.","ex":{"en":"He's the king of unlicensed boxing","cn":"他是黑市拳王。"}},{"pos":"N-COUNT 可数名词","cn":"（纸牌中的）老K","en":"A king is a playing card with a picture of a king on it.","ex":{"en":"...the king of diamonds.","cn":"方片K"}},{"pos":"N-COUNT 可数名词","cn":"（国际象棋中的）王","en":"In chess, the king is the most important piece. When you are in a position to capture your opponent's king, you win the game."},{"pos":"PHRASE 短语","cn":"过阔绰的生活；活得像个国王","en":"If you say that someone lives like a king, you mean that they are able to live in a very comfortable or luxurious way.","ex":{"en":"Executives lived like kings. The top thirty-one executives were paid a total of $14.2 million.","cn":"经理们活得像国王一样。职位最高的31名经理的薪金总额达到了1,420万美元。"}},{"pos":"","cn":"","en":"a king's ransom→see: ;"}]},"examples":[{"en":"The lion is the king of the jungle.","cn":"狮子是丛林之王。"},{"en":"the kings and queens of England","cn":"英国国王和王后"}]},"knife":{"oxford":{"phon":"naɪf","pos":"noun","senses":[{"en":"a sharp blade (= metal edge) with a handle, used for cutting or as a weapon","cn":"刀","lab":"figurative","ex":{"en":"knives and forks","cn":"刀叉"}},{"en":"to injure or kill somebody with a knife","cn":"用刀伤害（或杀害）","ex":{"en":"She knifed him in the back.","cn":"她用小刀刺了他的背"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"刀","en":"A knife is a tool for cutting or a weapon and consists of a flat piece of metal with a sharp edge on the end of a handle.","ex":{"en":"...a knife and fork","cn":"一副刀叉"}},{"pos":"VERB 动词","cn":"用刀伤害","en":"To knife someone means to attack and injure them with a knife.","ex":{"en":"Dawson takes revenge on the man by knifing him to death","cn":"道森用刀杀死了他的仇人。"}},{"pos":"N-COUNT 可数名词","cn":"手术刀","en":"A surgeon's knife is a piece of equipment used to cut flesh and organs during operations. It is made of metal and has a very thin sharp edge."},{"pos":"PHRASE 短语","cn":"接受手术；动手术","en":"If you go under the knife, you have an operation in a hospital.","ex":{"en":"Kelly was about to go under the knife when her surgeon stopped everything.","cn":"凯莉的手术就要开始时被她的外科医生给叫停了。"}},{"pos":"PHRASE 短语","cn":"轻而易举；毫无困难","en":"If someone does something like a knife through butter or like a hot knife through butter, they do it very easily.","ex":{"en":"Spending by Japanese companies has left them more competitive than companies in other nations. They will be cutting through the competition like a hot knife through butter.","cn":"日本公司的支出使得它们比其他国家的公司更具竞争力。它们将在竞争中轻而易举地取胜。"}},{"pos":"PHRASE 短语","cn":"（紧张的气氛）使人透不过气来","en":"If you have been in a place where there was a very tense atmosphere, you can say that you could have cut the atmosphere with a knife.","ex":{"en":"Officials hung the flag upside down. You could have cut the atmosphere with a knife.","cn":"官员们把旗子挂倒了。气氛紧张得让人透不过气来。"}},{"pos":"PHRASE 短语","cn":"对…磨刀霍霍；对…兴师问罪","en":"If a lot of people want something unpleasant to happen to someone, for example if they want them to lose their job, you can say that the knives are out for that person.","ex":{"en":"The Party knives are out for the leader.","cn":"该党派要向其领导人开刀了。"}},{"pos":"PHRASE 短语","cn":"落井下石；往伤口上撒盐","en":"If you twist the knife or if you turn the knife in someone's wound, you do or say something to make an unpleasant situation they are in even more unpleasant.","ex":{"en":"Travis twisted the knife by laughing at her","cn":"特拉维斯火上浇油般地嘲笑她。"}}]},"media":{"img":["media/pic/cutlery_diningroom_comp.jpg","media/thumb/knife.jpg"],"uk":"media/uk/knife__gb_1.mp3","us":"media/us/knife__us_1.mp3"},"examples":[{"en":"She was murdered in a frenzied knife attack.","cn":"她被乱刀残杀。"},{"en":"a bread knife (= one for cutting bread)","cn":"切面包刀"}]},"knock":{"media":{"uk":"media/uk/knock__gb_1.mp3","us":"media/us/knock__us_1.mp3"},"oxford":{"phon":"nɒk","pos":"verb","senses":[{"en":"to hit a door, etc. in order to attract attention","cn":"敲；击","g":"[intransitive]","sc":"at door/window","ex":{"en":"He knocked three times and waited.","cn":"他敲了三下门就等着。"}},{"en":"to hit something hard, often by accident","cn":"（意外）撞击，碰到","g":"[transitive, intransitive]","sc":"hit","ex":{"en":"Be careful you don't knock your head on this low beam.","cn":"小心，别把头撞在这矮梁上。"}},{"en":"to hit something so that it moves or breaks","cn":"打掉；敲动；打破","g":"[transitive]","lab":"figurative","sc":"hit","ex":{"en":"He'd knocked over a glass of water.","cn":"他打翻了一杯水。"}},{"en":"to put somebody/something into a particular state by hitting them/it","cn":"把…撞击成（某种状态）","g":"[transitive]","sc":"hit","ex":{"en":"The blow knocked me flat.","cn":"那一拳把我打倒在地。"}},{"en":"to make a hole in something by hitting it hard","cn":"打，凿（洞）","g":"[transitive]","sc":"hit","ex":{"en":"They managed to knock a hole in the wall.","cn":"他们设法在墙上凿了个洞。"}},{"en":"if your heart knocks, it beats hard; if your knees knock, they shake, for example from fear","cn":"（心）怦怦跳；（膝盖）打哆嗦","g":"[intransitive]","sc":"of heart/knees","ex":{"en":"My heart was knocking wildly.","cn":"我的心怦怦直跳。"}},{"en":"to make a regular sound of metal hitting metal, especially because there is something wrong","cn":"（尤指因故障）发碰撞声，嘭嘭作响","g":"[intransitive]","sc":"of engine/pipes"},{"en":"to criticize somebody/something, especially when it happens unfairly","cn":"（不公平地）批评；贬责；挑剔；非难","g":"[transitive]","lab":"informal","sc":"criticize","ex":{"en":"The newspapers are always knocking the England team.","cn":"报纸总是攻击英格兰队。"}},{"en":"the sound of somebody hitting a door, window, etc. with their hand or with something hard to attract attention","cn":"敲击声；敲门（或窗等）声","sc":"at door/window","ex":{"en":"There was a knock at the door.","cn":"有敲门声。"},"pos":"noun"},{"en":"a sharp hit from something hard","cn":"捶击；敲击；撞击","sc":"hit","ex":{"en":"He got a nasty knock on the head.","cn":"他头部遭到重重一击。"},"pos":"noun"},{"en":"a bad experience that makes somebody/something less confident or successful","cn":"挫折；打击","sc":"bad experience","ex":{"en":"Her confidence took a further knock when she lost her job.","cn":"当她失业后，她的信心进一步受到打击。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"敲；击","en":"If you knock on something such as a door or window, you hit it, usually several times, to attract someone's attention.","ex":{"en":"She went directly to Simon's apartment and knocked on the door","cn":"她直奔西蒙的房间，敲了敲门。"}},{"pos":"VERB 动词","cn":"碰，撞；（尤指）碰倒，撞倒，敲动","en":"If you knock something, you touch or hit it roughly, especially so that it falls or moves.","ex":{"en":"She accidentally knocked the tea tin off the shelf","cn":"她不小心把架子上的茶叶罐碰了下来。"}},{"pos":"VERB 动词","cn":"打通（房间或建筑）","en":"If someone knocks two rooms or buildings into one, or knocks them together, they make them form one room or building by removing a wall.","ex":{"en":"They decided to knock the two rooms into one","cn":"他们决定把两间屋子打通连成一间。"}},{"pos":"VERB 动词","cn":"把…撞击到（某个位置）；把…打成（某种状态）","en":"To knock someone into a particular position or condition means to hit them very hard so that they fall over or become unconscious.","ex":{"en":"The third wave was so strong it knocked me backwards","cn":"第3波浪太大了，把我打了回去。"}},{"pos":"VERB 动词","cn":"使失去（某种品质或特征）","en":"To knock a particular quality or characteristic out of someone means to make them lose it.","ex":{"en":"The stories of his links with the actress had knocked the fun out of him","cn":"有关他与那位女演员有关系的传闻使他很不开心。"}},{"pos":"VERB 动词","cn":"发碰撞声；砰砰作响","en":"If something knocks, it makes a repeated sharp banging noise.","ex":{"en":"His old truck, knocking and smoking, pulled down the road and out of sight.","cn":"他那辆旧卡车一边冒着烟一边哐里哐啷地沿路向前驶去，直到驶出了视线。"}},{"pos":"VERB 动词","cn":"批评；贬责；挑剔；非难","en":"If you knock something or someone, you criticize them and say unpleasant things about them.","ex":{"en":"I'm not knocking them: if they want to do it, it's up to them","cn":"我不是批评他们：想不想做那件事取决于他们。"}},{"pos":"N-COUNT 可数名词","cn":"打击","en":"If someone receives a knock, they have an unpleasant experience which prevents them from achieving something or which causes them to change their attitudes or plans.","ex":{"en":"What they said was a real knock to my self-confidence","cn":"他们的话是对我自信心的一次重大打击。"}},{"pos":"PHRASE 短语","cn":"（尤指以相貌）给…留下深刻印象，使…倾倒","en":"To knock them dead means to impress people a great deal, especially with your appearance.","ex":{"en":"Glamorous make-up is best reserved for days when you want to go all out to knock 'em dead.","cn":"魅惑彩妆最好留到你竭力想把所有人都迷倒的时候。"}},{"pos":"PHRASE 短语","cn":"停止干扰;打住","en":"If you tell someone to knock it off, you are telling them to stop doing something that is annoying you.","ex":{"en":"Will you just knock it off!","cn":"别闹了！"}},{"pos":"","cn":"","en":"to knock peoples' heads together→see: ; to knock something on the head→see: ; to knock someone or something into shape→see: ; to be knocked sideways→see: ;"},{"pos":"","cn":"","en":"相关词组：knock about knock around knock back knock down knock off knock out knock over knock together knock up"}]},"examples":[{"en":"‘E-books?’ ‘ Don't knock it — there's a great future in e-books.’ “","cn":"电子书？” “别贬损它，电子书的前景大着呢。”"},{"en":"The recession knocked on the head any idea of expanding the company.","cn":"经济衰退使扩展公司的任何想法都化为泡影。"}]},"kind":{"media":{"uk":"media/uk/kind__gb_1.mp3","us":"media/us/kind__us_1.mp3"},"oxford":{"phon":"kaɪnd","pos":"noun","senses":[{"en":"a group of people or things that are the same in some way; a particular variety or type","cn":"同类的人（或事物）；种类","ex":{"en":"three kinds of cakes/cake","cn":"三种蛋糕"}},{"en":"caring about others; gentle, friendly and generous","cn":"体贴的；慈祥的；友好的；宽容的","lab":"figurative","ex":{"en":"a very kind and helpful person","cn":"肯帮忙的好人"},"pos":"adjective"},{"en":"used to make a polite request or give an order","cn":"（客气请求或命令）","lab":"formal","ex":{"en":"Would you be kind enough to close the window?","cn":"请把窗子关上好吗？"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"种类","en":"If you talk about a particular kind of thing, you are talking about one of the types or sorts of that thing.","ex":{"en":"The party needs a different kind of leadership","cn":"该党需要一种不同的领导风格。"}},{"pos":"N-COUNT 可数名词","cn":"同类人","en":"If you refer to someone's kind, you are referring to all the other people that are like them or that belong to the same class or set.","ex":{"en":"I hate Lewis and his kind just as much as you do","cn":"我和你一样痛恨刘易斯之流。"}},{"pos":"PHRASE 短语","cn":"各种类型的；五花八门的","en":"You can use all kinds of to emphasize that there are a great number and variety of particular things or people.","ex":{"en":"Adoption can fail for all kinds of reasons","cn":"收养不成功可能有各种原因。"}},{"pos":"PHRASE 短语","cn":"稍微；有几分；有点儿","en":"You use kind of when you want to say that something or someone can be roughly described in a particular way.","ex":{"en":"It was kind of sad, really","cn":"有点儿让人难过，真的。"}},{"pos":"PHRASE 短语","cn":"名不副实，徒有其名（指不如本应有的那么好）","en":"You can use of a kind to indicate that something is not as good as it might be expected to be, but that it seems to be the best that is possible or available.","ex":{"en":"There is good news of a kind for the Prime Minister","cn":"对总理来说也算是有个好消息。"}},{"pos":"PHRASE 短语","cn":"独一无二的；独特的","en":"If you refer to someone or something as one of a kind, you mean that there is nobody or nothing else like them.","ex":{"en":"She's a very unusual woman, one of a kind.","cn":"她是个非常与众不同的女人，是独一无二的。"}},{"pos":"PHRASE 短语","cn":"两个/三个/四个同一类的","en":"If you refer, for example, to two, three, or four of a kind, you mean two, three, or four similar people or things that seem to go well or belong together.","ex":{"en":"They were two of a kind, from the same sort of background.","cn":"他们俩是一类人，有相同的背景。"}},{"pos":"PHRASE 短语","cn":"以同样的方式","en":"If you respond in kind, you react to something that someone has done to you by doing the same thing to them.","ex":{"en":"They hurled defiant taunts at the riot police, who responded in kind.","cn":"他们向防暴警察挑衅大骂，防暴警察同样回骂他们。"}},{"pos":"PHRASE 短语","cn":"以实物支付；以货代款；以服务偿付","en":"If you pay a debt in kind, you pay it in the form of goods or services and not money.","ex":{"en":"Inflation and the shortage of banknotes has forced factories to pay their workers in kind.","cn":"通货膨胀和纸币短缺使工厂不得不以实物抵付工人的工资。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"慈祥的；体贴的；乐于助人的","en":"Someone who is kind behaves in a gentle, caring, and helpful way towards other people.","ex":{"en":"She is warm-hearted and kind to everyone and everything","cn":"她对每个人每件事都很热心、宽厚。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"请…，…可以吗（表示坚定且客气地请求某人做某事）","en":"You can use kind in expressions such as please be so kind as to and would you be kind enough to in order to ask someone to do something in a firm but polite way.","ex":{"en":"Please be so kind as to see to it that all the alterations are made at once!","cn":"请务必立即执行变更！"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"突出优点的；使胜过实物的","en":"Something that is kind emphasizes the good qualities in something, and perhaps makes it appear better than it really is.","ex":{"en":"Summer clothes are invariably less kind to fuller figures.","cn":"体形较丰满的人穿夏装总是不那么好看。"}}]},"examples":[{"en":"She insulted him and he responded in kind.","cn":"她侮辱了他，他也以其人之道还治其人之身。"},{"en":"‘He's resigning.’ ‘I'd suspected something of the kind.’ “","cn":"他要辞职了。” “我料到会有这样的事。”"}]},"kick":{"oxford":{"phon":"kɪk","pos":"verb","senses":[{"en":"to hit somebody/something with your foot","cn":"踢；踹","g":"[transitive, intransitive]","ex":{"en":"Stop kicking—it hurts!","cn":"别踢了，好痛！"}},{"en":"to move your legs as if you were kicking something","cn":"踢蹬；踢（腿）","g":"[transitive, intransitive]","ex":{"en":"The child was dragged away, kicking and screaming.","cn":"这孩子又踢又叫地被拖走了。"}},{"en":"to be annoyed with yourself because you have done something stupid, missed an opportunity, etc.","cn":"（因干了蠢事、失去良机等）对（自己）生气","g":"[transitive]","lab":"informal","ex":{"en":"He'll kick himself when he finds out he could have had the job.","cn":"一旦发现他本可以得到这个工作，他会感到懊恼的。"}},{"en":"to score points by kicking the ball","cn":"踢球得分；射门得分","g":"[transitive]","ex":{"en":"to kick a penalty/goal","cn":"罚点球得分；射门得分"}},{"en":"to stop doing something harmful that you have done for a long time","cn":"戒除恶习；戒毒；戒酒","g":"[transitive]","lab":"informal","ex":{"en":"He had been smoking for 15 years and wanted to kick the habit.","cn":"他已经吸烟 15 年了，然后想戒掉这个习惯。"}},{"en":"a movement with the foot or the leg, usually to hit something with the foot","cn":"踢；踢脚；踢腿","ex":{"en":"the first kick of the game","cn":"比赛的开球"},"pos":"noun"},{"en":"a strong feeling of excitement and pleasure","cn":"极度刺激；极度兴奋；极大的乐趣","lab":"informal","ex":{"en":"I get a kick out of driving fast cars.","cn":"开快车给我带来极大的乐趣。"},"pos":"noun"},{"en":"the strong effect that a drug or an alcoholic drink has","cn":"（毒品或酒精的）效力，刺激性","g":"[usually singular]","lab":"informal","ex":{"en":"This drink has quite a kick.","cn":"这酒的劲相当大。"},"pos":"noun"},{"en":"a soft shoe that you wear for sports or as informal clothing","cn":"运动鞋；便鞋","g":"[usually plural]","lab":"North American English, informal，，","ex":{"en":"The actor wore denim, a simple tee and a nice pair of kicks.","cn":"这位演员穿着牛仔服，一件简单的 T 恤和一双漂亮的便鞋。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"踢；踹","en":"If you kick someone or something, you hit them forcefully with your foot.","ex":{"en":"He kicked the door hard","cn":"他使劲儿踢门。"}},{"pos":"VERB 动词","cn":"踢（球或其他物体）","en":"When you kick a ball or other object, you hit it with your foot so that it moves through the air.","ex":{"en":"I went to kick the ball and I completely missed it","cn":"我去踢球却踢了个空。"}},{"pos":"VERB 动词","cn":"踢蹬；踢（腿）","en":"If you kick or if you kick your legs, you move your legs with very quick, small, and forceful movements, once or repeatedly.","ex":{"en":"They were dragged away struggling and kicking","cn":"他们被拖走时挣扎着又踢又蹬。"}},{"pos":"VERB 动词","cn":"踢（腿）","en":"If you kick your legs, you lift your legs up very high one after the other, for example when you are dancing.","ex":{"en":"He was kicking his legs like a Can Can dancer","cn":"他像跳康康舞一样踢着腿。"}},{"pos":"VERB 动词","cn":"戒除（恶习）","en":"If you kick a habit, you stop doing something that is bad for you and that you find difficult to stop doing.","ex":{"en":"She's kicked her drug habit and learned that her life has value","cn":"她已经戒了毒，并且认识到了生命可贵。"}},{"pos":"N-SING 单数名词","cn":"极度兴奋；极度刺激；极大的乐趣","en":"If something gives you a kick, it makes you feel very excited or very happy for a short period of time.","ex":{"en":"I got a kick out of seeing my name in print.","cn":"当看到我的名字印成铅字时，我感到无比兴奋。"}},{"pos":"PHRASE 短语","cn":"落井下石","en":"If you say that someone kicks you when you are down, you think they are behaving unfairly because they are attacking you when you are in a weak position.","ex":{"en":"In the end I just couldn't kick Jimmy when he was down.","cn":"最后我就是无法做到在吉米倒霉时落井下石。"}},{"pos":"PHRASE 短语","cn":"为了寻求刺激","en":"If you say that someone does something for kicks, you mean that they do it because they think it will be exciting.","ex":{"en":"They made a few small bets for kicks.","cn":"他们觉得好玩便小赌了几把。"}},{"pos":"PHRASE 短语","cn":"被强拉硬拽;极不愿意","en":"If you say that someone is dragged kicking and screaming into a particular course of action, you are emphasizing that they are very unwilling to do what they are being made to do.","ex":{"en":"He had to be dragged kicking and screaming into action.","cn":"他要被强拉硬拽才肯行动起来。"}},{"pos":"PHRASE 短语","cn":"令人极度失望的事；重大的挫折","en":"If you describe an event as a kick in the teeth, you are emphasizing that it is very disappointing and upsetting.","ex":{"en":"We've been struggling for years and it's a real kick in the teeth to see a new band make it ahead of us.","cn":"我们奋斗了多年，看到一支新的乐队反而超越了我们，真让人大失所望。"}},{"pos":"PHRASE 短语","cn":"我真生自己的气/ 你会感到懊恼的","en":"You use kick yourself in expressions such as I could have kicked myself and you're going to kick yourself to indicate that you were annoyed or are going to be annoyed that you got something wrong.","ex":{"en":"I was still kicking myself for not paying attention","cn":"我仍在怪自己没有注意。"}},{"pos":"","cn":"","en":"alive and kicking→see: ; to kick someone's ass→see: ; to kick the bucket→see: ; to kick up a fuss→see: ;"},{"pos":"","cn":"","en":"相关词组：kick against kick around kick back kick down kick in kick off kick out kick up"}]},"media":{"uk":"media/uk/kick__gb_1.mp3","us":"media/us/kick__us_1.mp3"},"examples":[{"en":"He'll kick himself when he finds out he could have had the job.","cn":"一旦发现他本可以得到这个工作，他会感到懊恼的。"},{"en":"He tends to deal with disputes by kicking them into the long grass.","cn":"他处理争议的方法往往是置之不理。"}]},"killing":{"oxford":{"phon":"ˈkɪlɪŋ","pos":"noun","senses":[{"en":"an act of killing somebody deliberately","cn":"故意杀人；谋杀","lab":"British English","ex":{"en":"Their leader condemned the torture and killing of innocent civilians.","cn":"他们的领导人严词谴责虐待和杀戮无辜平民的行为。"}},{"en":"making you very tired","cn":"使人筋疲力尽的","ex":{"en":"a killing schedule","cn":"排得满满当当的时间表"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"杀害;谋杀","en":"A killing is an act of deliberately killing a person.","ex":{"en":"This is a brutal killing.","cn":"这是残忍的谋杀。"}},{"pos":"PHRASE 短语","cn":"发大财；获取暴利","en":"If you make a killing, you make a large profit very quickly and easily.","ex":{"en":"They have made a killing on the deal.","cn":"他们在这笔交易上赚了大钱。"}}]},"media":{"uk":"media/uk/killing__gb_1.mp3","us":"media/us/killing__us_1.mp3"},"examples":[{"en":"a killing schedule","cn":"排得满满当当的时间表"},{"en":"brutal killings","cn":"残杀"}],"base":"kill"},"kill":{"media":{"uk":"media/uk/kill__gb_1.mp3","us":"media/us/kill__us_1.mp3"},"oxford":{"phon":"kɪl","pos":"verb","senses":[{"en":"to make somebody/something die","cn":"杀死；弄死；导致死亡","g":"[transitive, intransitive]","lab":"informal","ex":{"en":"Cancer kills thousands of people every year.","cn":"每年数以千计的人死于癌症。"}},{"en":"to destroy something or make it less good; to make something stop","cn":"毁灭；破坏；扼杀；使停止","g":"[transitive]","ex":{"en":"to kill a rumour","cn":"平息谣言"}},{"en":"to switch off a light or engine; to stop a computer program or process","cn":"关掉；使（计算机程序）停止运行","g":"[transitive]","lab":"informal","ex":{"en":"She killed the engine and climbed out.","cn":"她关掉发动机，爬了出来。"}},{"en":"to cause somebody pain","cn":"使痛苦；使疼痛","g":"[transitive]","lab":"informal","ex":{"en":"My feet are killing me.","cn":"我的双脚痛死了。"}},{"en":"to make somebody laugh a lot","cn":"使笑得前仰后合；使笑死了","g":"[transitive]","lab":"especially North American English","ex":{"en":"Stop it! You're killing me!","cn":"别说了！你都把我笑死了！"}},{"en":"an act of killing, especially when an animal is hunted or killed","cn":"杀死，捕杀（尤指动物）","ex":{"en":"A cat often plays with a mouse before the kill.","cn":"猫在咬死老鼠之前常常要耍弄它一番。"},"pos":"noun"},{"en":"an animal that has been hunted and killed","cn":"被捕杀的动物；猎物","ex":{"en":"lions feeding on their kill","cn":"正在吃猎物的狮子"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"杀死；弄死;导致死亡","en":"If a person, animal, or other living thing is killed, something or someone causes them to die.","ex":{"en":"More than 1,000 people have been killed by the armed forces","cn":"1,000多人被武装部队杀死。"}},{"pos":"N-COUNT 可数名词","cn":"杀死，捕杀（动物）","en":"The act of killing an animal after hunting it is referred to as the kill .","ex":{"en":"After the kill the men and old women collect in an open space and eat a meal of whale meat.","cn":"捕杀过后，男人们和老年妇女们聚集到一片空地上吃了一顿鲸鱼肉。"}},{"pos":"VERB 动词","cn":"毁灭；破坏；扼杀；使停止","en":"If someone or something kills a project, activity, or idea, they completely destroy or end it.","ex":{"en":"His objective was to kill the space station project altogether","cn":"他的目的是使空间站项目全面停止。"}},{"pos":"VERB 动词","cn":"使减轻（疼痛）","en":"If something kills pain, it weakens it so that it is no longer as strong as it was.","ex":{"en":"He was forced to take opium to kill the pain.","cn":"他被迫服用鸦片来止痛。"}},{"pos":"VERB 动词","cn":"使痛苦；使疼痛；折磨","en":"If you say that something is killing you, you mean that it is causing you physical or emotional pain.","ex":{"en":"My feet are killing me.","cn":"我的脚疼死了。"}},{"pos":"VERB 动词","cn":"竭尽全力；极力","en":"If you say that you kill yourself to do something, you are emphasizing that you make a great effort to do it, even though it causes you a lot of trouble or suffering.","ex":{"en":"You shouldn't always have to kill yourself to do well.","cn":"你不该总是为了做到尽善尽美而累坏自己。"}},{"pos":"VERB 动词","cn":"（因对…极度愤怒而）想杀死","en":"If you say that you will kill someone for something they have done, you are emphasizing that you are extremely angry with them.","ex":{"en":"Tell Richard I'm going to kill him when I get hold of him.","cn":"告诉理查德，一旦抓住他，我要杀了他。"}},{"pos":"VERB 动词","cn":"致命；要命","en":"If you say that something will not kill you, you mean that it is not really as difficult or unpleasant as it might seem.","ex":{"en":"Three or four more weeks won't kill me!","cn":"再过3周或4周不会要了我的命！"}},{"pos":"VERB 动词","cn":"消磨（时间）；打发（时光)","en":"If you are killing time, you are doing something because you have some time available, not because you really want to do it.","ex":{"en":"I'm just killing time until I can talk to the other witnesses","cn":"在和其他目击者交谈前我只是在打发时间。"}},{"pos":"PHRASE 短语","cn":"(表示强调)即使很难，即便很费力","en":"If you say that you will do something if it kills you, you are emphasizing that you are determined to do it even though it is extremely difficult or painful.","ex":{"en":"I'll make this marriage work if it kills me.","cn":"再难我也要努力使这桩婚姻幸福美满。"}},{"pos":"PHRASE 短语","cn":"使笑得前仰后合；使笑死了","en":"If you say that you killed yourself laughing, you are emphasizing that you laughed a lot because you thought something was extremely funny."},{"pos":"PHRASE 短语","cn":"借机行事；伺机而动","en":"If you move in for the kill or if you close in for the kill, you take advantage of a changed situation in order to do something that you have been preparing to do.","ex":{"en":"Seeing his chance, Dennis moved in for the kill.","cn":"看到机会来了，丹尼斯开始采取行动。"}},{"pos":"","cn":"","en":"to kill two birds with one stone→see: ; dressed to kill→see: ; to kill the goose that lays the golden egg→see: ; to be killed outright→see: ;"},{"pos":"","cn":"","en":"相关词组：kill off"}]},"examples":[{"en":"Don't kill yourself trying to get the work done by tomorrow. It can wait.","cn":"别为了赶着明天把事情干完而累坏身体。这事可以等一等嘛。"},{"en":"Do you agree that television kills conversation?","cn":"电视扼杀人与人之间的交谈，你同意这种说法吗？"}]},"knees":{"lemma":"knee","media":{"uk":"media/uk/knee__gb_1.mp3","us":"media/us/knee__us_1.mp3"}},"kebab":{"media":{"uk":"media/uk/kebab__gb_1.mp3","us":"media/us/kebab__us_1.mp3"},"oxford":{"phon":"kɪˈbæb","pos":"noun","senses":[{"en":"small pieces of meat and vegetables cooked on a wooden or metal stick","cn":"烤肉串"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"烤串；（与皮塔饼一起吃的）烤肉片","en":"A kebab is pieces of meat or vegetables grilled on a long thin stick, or slices of grilled meat served in pitta bread."}]}},"knowledge":{"media":{"uk":"media/uk/knowledge__gb_1.mp3","us":"media/us/knowledge__us_1.mp3"},"oxford":{"phon":"ˈnɒlɪdʒ","pos":"noun","senses":[{"en":"the information, understanding and skills that you gain through education or experience","cn":"知识；学问；学识","g":"[uncountable, singular]","ex":{"en":"scientific/technical knowledge and skills","cn":"科学／技术知识和技能"}},{"en":"the state of knowing about a particular fact or situation","cn":"知晓；知悉；了解","g":"[uncountable]","ex":{"en":"He denied all knowledge of the affair.","cn":"他否认知道此事。"}},{"en":"information, considered as a resource to be used and supplied in industry, rather than producing goods","cn":"信息，知识（与产品制造相对）","ex":{"en":"the shift toward a knowledge economy","cn":"向知识经济的转变"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"知识；学问；学识","en":"Knowledge is information and understanding about a subject which a person has, or which all people have.","ex":{"en":"She told Parliament she had no knowledge of the affair.","cn":"她告诉议会她对此事并不知情。"}},{"pos":"PHRASE 短语","cn":"据…所知","en":"If you say that something is true to your knowledge or to the best of your knowledge, you mean that you believe it to be true but it is possible that you do not know all the facts.","ex":{"en":"Alec never carried a gun to my knowledge","cn":"据我所知亚历克从来不带枪。"}},{"pos":"PHRASE 短语","cn":"因知道…而放心","en":"If you do something safe in the knowledge that something else is the case, you do the first thing confidently because you are sure of the second thing.","ex":{"en":"You can let your kids play here, safe in the knowledge that they won't get sunburn.","cn":"你可以放心让孩子们在这儿玩，他们肯定不会晒黑。"}}]},"examples":[{"en":"I went to sleep secure in the knowledge that I was not alone in the house.","cn":"我知道当时不是只有我一人在房子里，就放心地睡觉了。"},{"en":"The film was made with the Prince's full knowledge and approval.","cn":"这部影片是在王子充分了解和认可的情况下拍摄的。"}]},"kings":{"lemma":"king","media":{"uk":"media/uk/king__gb_1.mp3","us":"media/us/king__us_1.mp3"}},"kangaroo":{"oxford":{"phon":"ˌkæŋɡəˈruː","pos":"noun","senses":[{"en":"a large Australian animal with a strong tail and back legs, that moves by jumping. The female carries its young in a pocket of skin (called a pouch) on the front of its body.","cn":"袋鼠（产于澳大利亚）","ex":{"en":"Kangaroos can jump immense distances.","cn":"袋鼠可以跳很远的距离。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"袋鼠（产于澳大利亚）","en":"A kangaroo is a large Australian animal which moves by jumping on its back legs. Female kangaroos carry their babies in a pouch on their stomach."}]},"media":{"img":["media/pic/marsupials_comp.jpg","media/thumb/kangaroo.jpg"],"uk":"media/uk/kangaroo__gb_1.mp3","us":"media/us/kangaroo__us_1.mp3"}},"knitted":{"oxford":{"phon":"ˈnɪtɪd","pos":"adjective","senses":[{"en":"made by knitting wool or another thread","cn":"编织的；针织的","ex":{"en":"knitted gloves","cn":"针织手套"}}]},"media":{"uk":"media/uk/knitted__gb_1.mp3","us":"media/us/knitted__us_1.mp3"},"examples":[{"en":"a white knit dress","cn":"白色针织连衣裙"},{"en":"a hand-knitted sweater","cn":"手工编织的毛衣"}]},"key":{"media":{"img":["media/ldoce/img/key.jpg","media/pic/key_comp.jpg"],"uk":"media/uk/key__gb_1.mp3","us":"media/us/key__us_1.mp3"},"oxford":{"phon":"kiː","pos":"noun","senses":[{"en":"a piece of metal with a special shape used for locking a door, starting a car, etc.","cn":"钥匙","sc":"tool for lock","ex":{"en":"to put/turn the key in the lock","cn":"把钥匙插入锁孔；转动锁孔中的钥匙"}},{"en":"a thing that makes you able to understand or achieve something","cn":"关键；要诀","g":"[usually singular]","lab":"especially North American English","sc":"most important thing","ex":{"en":"Persistence is the key if you want to get a job.","cn":"如果你想找到工作，坚持是关键。"}},{"en":"any of the buttons that you press to operate a computer, phone or typewriter","cn":"（计算机、电话或打字机的）键","sc":"on computer","ex":{"en":"Press the return key to enter the information.","cn":"按回车键录入信息。"}},{"en":"any of the wooden or metal parts that you press to play a piano and some other musical instruments","cn":"（钢琴或其他乐器的）键","sc":"on musical instrument","ex":{"en":"His hands flew over the piano keys.","cn":"他的双手飞过钢琴键。"}},{"en":"a set of related notes, based on a particular note. Pieces of music are usually written mainly using a particular key.","cn":"调","sc":"music","ex":{"en":"a sonata in the key of E flat major","cn":"一首降 E 大调奏鸣曲"}},{"en":"a set of answers to exercises or problems","cn":"答案；题解","sc":"answers","ex":{"en":"Check your answers in the key at the back of the book.","cn":"用书后的解答核对答案。"}},{"en":"an explanation of the symbols used on a map or plan","cn":"（地图或平面图的）符号说明，图例","sc":"on map","ex":{"en":"You can find the symbols in the key at the bottom of the page.","cn":"这些符号可以在页底的符号说明中找到。"}},{"en":"most important; essential","cn":"最重要的；主要的；关键的","ex":{"en":"the key issue/factor/point","cn":"关键问题／因素；要点"},"pos":"adjective"},{"en":"to put information into a computer using a keyboard","cn":"用键盘输入；键入","ex":{"en":"I was busy keying data.","cn":"我正忙着录入数据。"},"pos":"verb"},{"en":"to deliberately damage a car by scratching it with a key","cn":"用钥匙划坏（汽车）","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钥匙","en":"A key is a specially shaped piece of metal that you place in a lock and turn in order to open or lock a door, or to start or stop the engine of a vehicle.","ex":{"en":"They put the key in the door and entered","cn":"他们用钥匙打开门进去了。"}},{"pos":"N-COUNT 可数名词","cn":"（计算机或打字机的）键","en":"The keys on a computer keyboard or typewriter are the buttons that you press in order to operate it."},{"pos":"N-COUNT 可数名词","cn":"（钢琴或风琴的）键","en":"The keys of a piano or organ are the long narrow pieces of wood or plastic that you press in order to play it."},{"pos":"N-VAR 可变名词","cn":"（音乐的）调","en":"In music, a key is a scale of musical notes that starts on one specific note.","ex":{"en":"...the key of A minor.","cn":"A小调"}},{"pos":"N-COUNT 可数名词","cn":"（地图、图解或科技书籍的）略语表，符号表，凡例","en":"The key on a map or diagram or in a technical book is a list of the symbols or abbreviations used and their meanings.","ex":{"en":"You will find a key at the front of the book.","cn":"你会在书的前面找到略语表。"}},{"pos":"ADJ 形容词","cn":"最重要的；关键的","en":"The key person or thing in a group is the most important one.","ex":{"en":"He is expected to be the key witness at the trial","cn":"他将成为审判的关键证人。"}},{"pos":"N-COUNT 可数名词","cn":"关键；要诀","en":"The key to a desirable situation or result is the way in which it can be achieved.","ex":{"en":"The key to success is to be ready from the start","cn":"成功的关键在于从一开始就要准备充分。"}},{"pos":"See also:","cn":"","en":"under lock and key→see: ;"},{"pos":"","cn":"","en":"相关词组：key in"}]},"examples":[{"en":"The driver of the car probably holds the key to solving the crime.","cn":"这位汽车司机很可能掌握侦破这一罪案的关键证据。"},{"en":"( especially NAmE ) The key is, how long can the federal government control the inflation rate?","cn":"关键在于联邦政府对通货膨胀率的控制能维持多久？"}]},"kindly":{"media":{"uk":"media/uk/kindly__gb_1.mp3","us":"media/us/kindly__us_1.mp3"},"oxford":{"phon":"ˈkaɪndli","pos":"adverb","senses":[{"en":"in a kind way","cn":"体贴地；慈祥地；友好地；宽容地","ex":{"en":"She spoke kindly to them.","cn":"她与他们亲切交谈。"}},{"en":"used to ask or tell somebody to do something, sometimes when you are annoyed","cn":"劳驾，请（用于请人或让人做某事，有时表现出说话人气恼）","lab":"old-fashioned or formal","ex":{"en":"Kindly leave me alone!","cn":"请不要打扰我！"}},{"en":"kind and caring","cn":"和善的；亲切的；关怀的；体贴的","ex":{"en":"The doctor was a quiet, kindly man.","cn":"医生是一个安静、和善的人。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"仁慈的；体贴的；有同情心的","en":"A kindly person is kind, caring, and sympathetic.","ex":{"en":"He was a stern critic but an extremely kindly man.","cn":"他是个苛刻的批评家，但却是个非常善良的人。"}},{"pos":"ADV-GRADED 副词","cn":"体贴地；友好地","en":"If someone kindly does something for you, they act in a thoughtful and helpful way.","ex":{"en":"He kindly carried our picnic in a rucksack","cn":"他很体贴地背着装有我们野餐食物的背包。"}},{"pos":"ADV 副词","cn":"（表示因有权让人做某事或对其恼怒）劳驾，请","en":"If someone asks you to kindly do something, they are asking you in a way which shows that they have authority over you, or that they are angry with you.","ex":{"en":"Will you kindly obey the instructions I am about to give?","cn":"劳驾你服从我要给出的指令好不好？"}},{"pos":"PHRASE 短语","cn":"支持；赞同","en":"If you look kindly on or look kindly upon someone or something, you support them or approve of what they are doing.","ex":{"en":"Recent historical work looks kindly on the regime.","cn":"近来的历史论著对该政权持赞同态度。"}},{"pos":"PHRASE 短语","cn":"不喜欢","en":"If someone does not take kindly to something, they do not like it.","ex":{"en":"She did not take kindly to being offered advice","cn":"她不喜欢别人给她提建议。"}}]},"examples":[{"en":"Visitors are kindly requested to sign the book.","cn":"敬请参观者在这本册子上签名。"},{"en":"He hoped they would look kindly on his request.","cn":"他希望他们接受他的请求。"}]},"knives":{"lemma":"knife","media":{"uk":"media/uk/knives__gb_1.mp3","us":"media/us/knives__us_1.mp3"}},"kettle":{"oxford":{"phon":"ˈketl","pos":"noun","senses":[{"en":"a container with a lid, a handle and a spout, used for boiling water","cn":"（烧水用的）壶，水壶","lab":"British English","ex":{"en":"an electric kettle","cn":"电水壶"}},{"en":"to keep a group of people who are taking part in a demonstration or protest held in an area with no easy way out, in order to make them behave in a peaceful way again","cn":"围堵，圈围（将游行示威者限制在一定区域内使其不能轻易离开）","ex":{"en":"Hundreds of protesters were kettled at the start of the demonstration.","cn":"数百名抗议者在游行开始时就被警方围堵起来。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"水壶","en":"A kettle is a covered container that you use for boiling water. It has a handle, and a spout for the water to come out of.","ex":{"en":"I'll put the kettle on and make us some tea.","cn":"我去烧壶水给大家沏茶。"}},{"pos":"N-COUNT 可数名词","cn":"锅","en":"A kettle is a metal pot for boiling or cooking things in.","ex":{"en":"Put the meat into a small kettle.","cn":"把肉放进一个小锅里。"}},{"pos":"PHRASE 短语","cn":"完全不同的事物","en":"If you say that something is a different kettle of fish, you mean that it is very different from another related thing that you are talking about.","ex":{"en":"Playing for the reserve team is a totally different kettle of fish.","cn":"作为替补参加比赛完全是两码事。"}}]},"media":{"img":["media/pic/kettlecoffeemaker_appliances_comp.jpg","media/thumb/electrickettle.jpg","media/ldoce/img/ldoce_180.png"],"uk":"media/uk/kettle__gb_1.mp3","us":"media/us/kettle__us_1.mp3"},"examples":[{"en":"( BrE ) I'll put the kettle on (= start boiling some water) and make some tea.","cn":"让我来烧壶水沏茶。"},{"en":"I'll put the kettle on (= start boiling some water) and make some tea.","cn":""}]},"knowingly":{"media":{"uk":"media/uk/knowingly__gb_1.mp3","us":"media/us/knowingly__us_1.mp3"},"oxford":{"phon":"ˈnəʊɪŋli","pos":"adverb","senses":[{"en":"while knowing the truth or likely result of what you are doing","cn":"故意地；蓄意地","ex":{"en":"She was accused of knowingly making a false statement to the police.","cn":"她被指控故意向警方提供虚假供词。"}},{"en":"in a way that shows that you know or understand about something that is supposed to be secret","cn":"会意地；心照不宣地；知情地","ex":{"en":"He glanced at her knowingly.","cn":"他会意地看了她一眼。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"故意；蓄意地","en":"If you knowingly do something wrong, you do it even though you know it is wrong.","ex":{"en":"He repeated that he had never knowingly taken illegal drugs.","cn":"他再三强调自己从没有故意吸毒。"}}]},"examples":[{"en":"She was accused of knowingly making a false statement to the police.","cn":"她被指控故意向警方提供虚假供词。"},{"en":"He glanced at her knowingly.","cn":"他会意地看了她一眼。"}]},"kindergarten":{"oxford":{"phon":"ˈkɪndəɡɑːtn","pos":"noun","senses":[{"en":"a school or class to prepare children aged five for school","cn":"学前班","lab":"especially North American English","ex":{"en":"his first day at kindergarten","cn":"他在幼儿园的第一天"}},{"en":"nursery school (= a school for children between the ages of about two and five)","cn":"幼儿园","lab":"British English, Australian English, New Zealand English，，，，"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"幼儿园","en":"A kindergarten is an informal kind of school for very young children, where they learn things by playing.","ex":{"en":"She's in kindergarten now.","cn":"她目前在上幼儿园。"}}]},"media":{"uk":"media/uk/kindergarten__gb_1.mp3","us":"media/us/kindergarten__us_1.mp3"}},"kneel":{"media":{"uk":"media/uk/kneel__gb_1.mp3","us":"media/us/kneel__us_1.mp3"},"oxford":{"phon":"niːl","pos":"verb","senses":[{"en":"to be in or move into a position where your body is supported on your knee or knees","cn":"跪；跪着；跪下","ex":{"en":"a kneeling figure","cn":"跪着的人影"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"跪下；跪着","en":"When you kneel, you bend your legs so that your knees are touching the ground.","ex":{"en":"She knelt by the bed and prayed","cn":"她跪在床边祈祷。"}}]},"examples":[{"en":"We knelt (down) on the ground to examine the tracks.","cn":"我们跪在地上察看踪迹。"},{"en":"a kneeling figure","cn":"跪着的人影"}]},"keenly":{"oxford":{"phon":"ˈkiːnli","pos":"adverb","senses":[{"en":"in a way that involves strong or deep feelings or awareness","cn":"强烈的；浓厚的；深厚的","ex":{"en":"We were keenly aware of the danger.","cn":"我们深知其危险。"}},{"en":"in a way that involves quick understanding","cn":"敏锐地：以一种快速理解的方式","ex":{"en":"The dogs are keenly intelligent.","cn":"这些狗非常聪明。"}},{"en":"in a way that involves people competing very hard with each other for something","cn":"激烈的；紧张的","ex":{"en":"a keenly fought contest","cn":"争夺激烈的竞赛"}},{"en":"in a way that shows you are enthusiastic or want something very much","cn":"热切地；满怀热情地","ex":{"en":"They waited keenly to hear her speak.","cn":"他们热切地等待着听她讲话。"}},{"en":"in a way that involves keeping a price low in order to compete with other prices","cn":"低廉地","ex":{"en":"a keenly priced car","cn":"价格低廉的汽车"}}]},"media":{"uk":"media/uk/keenly__gb_1.mp3","us":"media/us/keenly__us_1.mp3"},"examples":[{"en":"We were keenly aware of the danger.","cn":"我们深知其危险。"},{"en":"a keenly fought contest","cn":"争夺激烈的比赛"}]},"kingdom":{"oxford":{"phon":"ˈkɪŋdəm","pos":"noun","senses":[{"en":"a country that has a king or queen as head of state (= official leader of the country)","cn":"王国","ex":{"en":"the United Kingdom","cn":"联合王国"}},{"en":"an area controlled by a particular person or where a particular thing or idea is important","cn":"管辖范围；领域"},{"en":"one of the three traditional divisions of the natural world","cn":"自然三界之一","ex":{"en":"the animal, vegetable and mineral kingdoms","cn":"动物界、植物界及矿物界"}},{"en":"one of the five major groups into which all living things are organized","cn":"界（生物的五大类别之一）","lab":"biology"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"王国","en":"A kingdom is a country or region that is ruled by a king or queen.","ex":{"en":"The kingdom's power declined.","cn":"王国的势力衰弱了。"}},{"pos":"N-COUNT 可数名词","cn":"管辖范围；领域","en":"A kingdom is a place or area that is thought to be under the control of a person or organization.","ex":{"en":"It was infamous as a kingdom of brigands, scoundrels, and slave-traders.","cn":"该地区因土匪、无赖和奴隶贩子猖獗而声名狼藉。"}},{"pos":"N-SING 单数名词","cn":"（动物或植物）界","en":"All the animals, birds, and insects in the world can be referred to together as the animal kingdom. All the plants can be referred to as the plant kingdom."}]},"media":{"uk":"media/uk/kingdom__gb_1.mp3","us":"media/us/kingdom__us_1.mp3"},"examples":[{"en":"the animal, vegetable and mineral kingdoms","cn":"动物界、植物界及矿物界"},{"en":"the kingdom of God (= heaven)","cn":"天国"}]},"keen":{"media":{"uk":"media/uk/keen__gb_1.mp3","us":"media/us/keen__us_1.mp3"},"oxford":{"phon":"kiːn","pos":"adjective","senses":[{"en":"wanting to do something or wanting something to happen very much","cn":"渴望；热切；热衷于","lab":"especially British English","sc":"eager/enthusiastic","ex":{"en":"John was very keen to help.","cn":"约翰很热心，愿意帮忙。"}},{"en":"enthusiastic about an activity or idea, etc.","cn":"热情的；热心的","g":"[usually before noun]","lab":"especially British English","sc":"eager/enthusiastic","ex":{"en":"a keen sportsman/gardener","cn":"热衷运动／园艺的人"}},{"en":"liking somebody/something very much; very interested in somebody/something","cn":"喜爱；（对…）着迷，有兴趣","lab":"British English, informal，，","sc":"liking somebody/something","ex":{"en":"They've been on a few dates together and Naomi seems really keen.","cn":"他们一起约会过几次，内奥米似乎非常热衷。"}},{"en":"quick to understand","cn":"思维敏捷的；机灵的；机智的","g":"[only before noun]","sc":"clever","ex":{"en":"a keen mind/intellect","cn":"敏捷的思考／头脑"}},{"en":"strong or deep","cn":"强烈的；浓厚的；深厚的","g":"[usually before noun]","sc":"ideas/feelings","ex":{"en":"a keen sense of tradition","cn":"强烈的传统意识"}},{"en":"highly developed","cn":"灵敏的；敏锐的","g":"[only before noun]","sc":"senses","ex":{"en":"Dogs have a keen sense of smell.","cn":"狗的嗅觉很灵敏。"}},{"en":"involving people competing very hard with each other for something","cn":"激烈的；紧张的","sc":"competition","ex":{"en":"There is keen competition for places at the college.","cn":"要在这所学院就读，竞争是非常激烈的。"}},{"en":"kept low in order to compete with other prices","cn":"低廉的；有竞争力的","lab":"especially British English","sc":"prices","ex":{"en":"The company hopes its keen pricing policy will increase sales.","cn":"该公司希望其低廉的定价政策能增加销量。"}},{"en":"extremely cold","cn":"寒冷刺骨的","lab":"literary","sc":"wind"},{"en":"having a sharp edge or point","cn":"锋利的；锐利的","g":"[usually before noun]","lab":"literary","sc":"knife"},{"en":"to make a loud, high sad sound, when somebody has died","cn":"（为死者）恸哭，哀号","pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"渴望的；热切的；热衷的","en":"If you are keen on doing something, you very much want to do it. If you are keen that something should happen, you very much want it to happen.","ex":{"en":"You're not keen on going, are you?","cn":"你不太想去，是吗？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对…）喜爱的，满怀热情的","en":"If you are keen on something, you like it a lot and are very enthusiastic about it.","ex":{"en":"I got quite keen on the idea","cn":"我对这个想法燃起了极大的热情。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(对某一活动)热情的，热心的","en":"You use keen to indicate that someone has a lot of enthusiasm for a particular activity and spends a lot of time doing it.","ex":{"en":"She was a keen amateur photographer.","cn":"她是业余摄影爱好者。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)生性热情的，兴趣广博的","en":"If you describe someone as keen, you mean that they have an enthusiastic nature and are interested in everything that they do.","ex":{"en":"He's a very keen student and works very hard","cn":"他是个很好学的学生，学习非常努力。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（兴趣或感情）浓厚的，强烈的","en":"A keen interest or emotion is one that is very intense.","ex":{"en":"He had retained a keen interest in the progress of the work.","cn":"他对那项工作的进展一直很关心。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（支持）热情的，积极的","en":"If you are a keen supporter of a cause, movement, or idea, you support it enthusiastically.","ex":{"en":"He's been a keen supporter of the Labour Party all his life","cn":"他一生都是工党的热情拥护者。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"思维敏捷的；机灵的；机智的","en":"If you say that someone has a keen mind, you mean that they are very clever and aware of what is happening around them.","ex":{"en":"They described him as a man of keen intellect","cn":"他们把他描述成一个才思敏捷的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（目光或听觉）灵敏的，敏锐的","en":"If you have a keen eye or ear, you are able to notice things that are difficult to detect.","ex":{"en":"...an amateur artist with a keen eye for detail","cn":"对细节非常敏感的业余画家"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对某人）倾心的,迷恋的","en":"If you are keen on someone, you find them sexually attractive and want to get to know them better.","ex":{"en":"Mick has always been very keen on Carla.","cn":"米克一直迷恋卡拉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（战斗或竞争）激烈的，紧张的","en":"A keen fight or competition is one in which the competitors are all trying very hard to win, and it is not easy to predict who will win.","ex":{"en":"There is expected to be a keen fight in the local elections.","cn":"预计地方选举的竞争会非常激烈。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（价格）低廉的，有竞争力的","en":"Keen prices are low and competitive.","ex":{"en":"The company negotiates very keen prices with their suppliers.","cn":"该公司通过讨价还价从供货商那里拿到了很低的价格。"}},{"pos":"VERB 动词","cn":"（为死者）恸哭，哀号","en":"If someone keens, they cry out or make sounds to express their sorrow at someone's death.","ex":{"en":"He tossed back his head and keened","cn":"他仰天恸哭起来。"}},{"pos":"PHRASE 短语","cn":"对…十分热衷；对…非常热情","en":"If you say that someone is mad keen on something, you are emphasizing that they are very enthusiastic about it.","ex":{"en":"So you're not mad keen on science then?","cn":"那么你对科学并不是太感兴趣了？"}}]},"examples":[{"en":"There is keen competition for places at the college.","cn":"要在这所学院就读竞争是非常激烈的。"},{"en":"We are keen that our school should get involved too.","cn":"我们盼着自己学校也参与其中。"}]},"kidney":{"media":{"uk":"media/uk/kidney__gb_1.mp3","us":"media/us/kidney__us_1.mp3","img":["media/ldoce/img/body.jpg"]},"oxford":{"phon":"ˈkɪdni","pos":"noun","senses":[{"en":"either of the two organs in the body that remove waste products from the blood and produce urine","cn":"肾；肾脏","g":"[countable]","ex":{"en":"a kidney infection","cn":"肾感染"}},{"en":"the kidneys of some animals that are cooked and eaten","cn":"（食用的）腰子","g":"[uncountable, countable]","ex":{"en":"steak and kidney pie","cn":"牛肉腰花馅饼"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"肾；肾脏","en":"Your kidneys are the organs in your body that take waste matter from your blood and send it out of your body as urine."},{"pos":"N-VAR 可变名词","cn":"（供食用的）腰子","en":"Kidneys are the kidneys of an animal, for example a lamb, calf, or pig, that are eaten as meat.","ex":{"en":"...lambs' kidneys.","cn":"羊腰子"}}]},"examples":[{"en":"steak and kidney pie","cn":"牛肉腰花馅饼"},{"en":"a kidney infection","cn":"肾感染"}]},"knee":{"media":{"uk":"media/uk/knee__gb_1.mp3","us":"media/us/knee__us_1.mp3"},"oxford":{"phon":"niː","pos":"noun","senses":[{"en":"the joint between the top and bottom parts of the leg where it bends in the middle","cn":"膝；膝盖；膝关节","ex":{"en":"a knee injury","cn":"膝关节受伤"}},{"en":"the part of a piece of clothing that covers the knee","cn":"（裤子的）膝部","ex":{"en":"I brushed the dust from the knees of my trousers.","cn":"我掸掉裤膝上的灰尘。"}},{"en":"the top surface of the upper part of the legs when you are sitting down","cn":"（坐下时）大腿朝上的面","ex":{"en":"Come and sit on Daddy's knee.","cn":"来坐在爸爸腿上。"}},{"en":"to hit or push somebody/something with your knee","cn":"用膝盖顶（或撞）","ex":{"en":"He kneed his attacker in the groin.","cn":"他用膝盖猛撞攻击者的下身。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"膝；膝盖；膝关节","en":"Your knee is the place where your leg bends.","ex":{"en":"He will receive physiotherapy on his damaged left knee.","cn":"因左膝受伤，他将接受物理治疗。"}},{"pos":"N-COUNT 可数名词","cn":"（坐下时）大腿朝上的面","en":"If something or someone is on your knee or on your knees, they are resting or sitting on the upper part of your legs when you are sitting down.","ex":{"en":"He sat with the package on his knees","cn":"他坐着，将包裹放在腿上。"}},{"pos":"N-COUNT 可数名词","cn":"（裤子的）膝部","en":"The knee on a piece of clothing is the part that covers your knee.","ex":{"en":"...jeans with holes at both knees.","cn":"两个膝部都有洞的牛仔裤"}},{"pos":"N-PLURAL 复数名词","cn":"膝部","en":"If you are on your knees, your legs are bent and your knees are on the ground.","ex":{"en":"She fell to the ground on her knees and prayed","cn":"她跪下祈祷。"}},{"pos":"VERB 动词","cn":"用膝盖顶","en":"If you knee someone, you hit them using your knee.","ex":{"en":"Ian kneed him in the groin.","cn":"伊恩用膝盖顶他的下身。"}},{"pos":"PHRASE 短语","cn":"摧毁；使瘫痪","en":"If a country or organization is brought to its knees, it is almost completely destroyed by someone or something.","ex":{"en":"The country was being brought to its knees by the loss of 2.4 million manufacturing jobs","cn":"该国因制造业丧失了240万个就业机会而遭到严重打击。"}}]},"examples":[{"en":"I grazed my knee when I fell.","cn":"我摔了一跤，把膝盖擦破了。"},{"en":"The strikes brought the industry to its knees.","cn":"罢工使得这个行业陷入瘫痪。"}]},"kilograms":{"lemma":"kilogram"},"kicks":{"lemma":"kick"},"kw":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"(in writing) kilowatt","cn":"（书写形式）千瓦","ex":{"en":"a 2kW electric fire","cn":"两千瓦的电炉"}}]},"media":{"us":"media/ldoce/hwd/ame/b/laad3kw.mp3"},"examples":[{"en":"a 2kW electric fire * 2","cn":"千瓦的电炉"},{"en":"a 2kW electric fire","cn":""}],"collins":{"senses":[{"pos":"","cn":"","en":"KW is a written abbreviation for (书面缩略=) kilowatt."}]}},"kg":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"kilogram(s)","cn":"千克；公斤","ex":{"en":"10kg","cn":"10 公斤"}},{"en":"the abbreviation for Knight of the Order of the Garter","cn":"吊袜带骑士团的缩写","ex":{"en":"Sir Thomas Bell KG","cn":"托马斯·贝尔嘉德勋爵士。"},"pos":""}]},"collins":{"senses":[{"pos":"","cn":"=) kilogram or kilograms.","en":"kg is an abbreviation for (缩略"}]},"media":{"uk":"media/ldoce/hwd/bre/5/lpd_kg.mp3","us":"media/ldoce/hwd/ame/5/lpd_kg.mp3"},"examples":[{"en":"10kg * 10","cn":"公斤"}]},"kebabs":{"lemma":"kebab"},"kits":{"lemma":"kit"},"kids":{"lemma":"kid"},"km":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"(in writing) kilometre(s)","cn":"（书写形式）千米，公里"}]},"media":{"us":"media/ldoce/hwd/ame/5/laad3km.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"km is a written abbreviation for (书面缩略=) kilometre."}]}},"knights":{"lemma":"knight"},"keeps":{"lemma":"keep"},"keys":{"lemma":"key"},"korean":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"朝鲜（或韩国）的；朝鲜（或韩国）人的；朝鲜（或韩）语的；朝鲜（或韩国）文化的","en":"Korean means belonging or relating to North or South Korea, or to their people, language, or culture."},{"pos":"N-COUNT 可数名词","cn":"朝鲜（或韩国）人；朝鲜（或韩国）裔人","en":"A Korean is a North or South Korean citizen, or a person of North or South Korean origin."},{"pos":"N-UNCOUNT 不可数名词","cn":"朝鲜语；韩国语","en":"Korean is the language spoken by people who live in North and South Korea."}]},"oxford":{"phon":"kəˈriːən","pos":"noun, adjective","senses":[{"en":"(a person) from North Korea or South Korea","cn":"朝鲜人；韩国人；朝鲜（人）的；韩国（人）的"}]}},"knocked":{"lemma":"knock"},"killed":{"lemma":"kill"},"knuckles":{"lemma":"knuckle"},"kinks":{"oxford":{"phon":"kɪŋk","pos":"noun","senses":[{"en":"a bend or twist in sth that is usually straight （","cn":"直线物体上的）弯，结"},{"en":"( informal, disapproving ) an unusual feature in a person's character or mind, especially one that does not seem normal","cn":"怪癖；怪念头；奇想"}]}},"kills":{"lemma":"kill"},"knows":{"lemma":"know"},"kissed":{"lemma":"kiss"},"kinds":{"lemma":"kind"},"kennels":{"lemma":"kennel"},"knot":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（用绳索、布或其他材料打的）结","en":"If you tie a knot in a piece of string, rope, cloth, or other material, you pass one end or part of it through a loop and pull it tight.","ex":{"en":"One lace had broken and been tied in a knot.","cn":"一条带子已经断了，打了个结。"}},{"pos":"VERB 动词","cn":"把（绳索、布或其他材料）打成结","en":"If you knot a piece of string, rope, cloth, or other material, you pass one end or part of it through a loop and pull it tight.","ex":{"en":"He knotted the laces securely together","cn":"他把带子紧紧地系在一起。"}},{"pos":"N-COUNT 可数名词","cn":"(挤在一起的)一群","en":"A knot of people is a group of people who are standing very close together.","ex":{"en":"A little knot of men stood clapping.","cn":"一小群人站在那儿鼓掌。"}},{"pos":"N-COUNT 可数名词","cn":"（通常由害怕或激动引起的胃的）痉挛，郁结","en":"If you feel a knot in your stomach, you get an uncomfortable tight feeling in your stomach, usually because you are afraid or excited.","ex":{"en":"There was a knot of tension in his stomach.","cn":"他紧张得心揪得紧紧的。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（因害怕或激动而）痉挛，紧缩，使痉挛","en":"If your stomach knots or if something knots it, it feels tight because you are afraid or excited.","ex":{"en":"I felt my stomach knot with apprehension","cn":"我很担忧，心都揪紧了。"}},{"pos":"VERB 动词","cn":"（通常因担心或愤怒而肌肉等）紧张，紧绷","en":"If part of your face or your muscles knot, they become tense, usually because you are worried or angry.","ex":{"en":"His forehead knotted in a frown.","cn":"他眉头紧锁。"}},{"pos":"N-COUNT 可数名词","cn":"（树枝上的）节子，节疤","en":"A knot in a piece of wood is a small hard area where a branch grew."},{"pos":"N-COUNT 可数名词","cn":"节（船、飞行器和风的速度计量单位）","en":"A knot is a unit of speed. The speed of ships, aircraft, and winds is measured in knots.","ex":{"en":"They travel at speeds of up to 30 knots.","cn":"他们以高达30节的速度行进。"}},{"pos":"PHRASE 短语","cn":"（使）感到迷惑不解；（使）急切","en":"If you tie yourself in knots, you get very confused and anxious.","ex":{"en":"The press agent tied himself in knots trying to apologise.","cn":"那个广告宣传人员急于道歉。"}},{"pos":"PHRASE 短语","cn":"结合；结婚","en":"If you say that two people tie the knot, you mean that they get married.","ex":{"en":"Len tied the knot with Kate five years ago.","cn":"莱恩5年前和凯特结婚了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"several people who are together in the same place","cn":""},{"en":"a large number of people who are all together in the same place","cn":""},{"en":"a group of people standing or sitting very close to each other, for example in order to see something or talk to someone","cn":""}]},"collocations":{"phrases":["ADV. securely, tightly | loosely | neatly | badly, clumsily | together I knotted the ropes together securely.","PREP. around/round She knotted the scarf loosely around her neck."]},"media":{"uk":"media/ldoce/hwd/bre/2/knot_v0205.mp3","us":"media/ldoce/hwd/ame/9/knot1.mp3","img":["media/pic/knot_comp.jpg","media/thumb/knot.jpg"]},"examples":[{"en":"She wore her hair loosely knotted on top of her head.","cn":"她在头顶上打了个松松的发髻。"},{"en":"Tie the two ropes together with a knot.","cn":"将这两根绳子打结系在一起。"}],"oxford":{"phon":"nɒt","pos":"noun","senses":[{"en":"a join made by tying together two pieces or ends of string, rope, etc.","cn":"（用绳索等打的）结","sc":"in string/rope","ex":{"en":"to tie a knot","cn":"打结"}},{"en":"a way of twisting hair into a small round shape at the back of the head","cn":"发髻","sc":"of hair","ex":{"en":"She had her hair in a knot.","cn":"她把头发打了个髻。"}},{"en":"a tight mass in something such as hair or wool, where it has become twisted together","cn":"（毛发纠缠在一起形成的）团，球，结","sc":"of hair","ex":{"en":"hair full of knots and tangles","cn":"缠绕打结的头发"}},{"en":"a hard round spot in a piece of wood where there was once a branch","cn":"节子；节疤","sc":"in wood"},{"en":"a small group of people standing close together","cn":"一小群人","sc":"group of people","ex":{"en":"Little knots of people had gathered at the entrance.","cn":"入口处聚集了一小群人。"}},{"en":"a tight, hard feeling in the stomach, throat, etc. caused by nerves, anger, etc.","cn":"（由紧张、恼怒等引起的胃、喉等的）痉挛，郁结，哽咽，哽塞","sc":"of muscles","ex":{"en":"My stomach was in knots.","cn":"我（紧张得）胃痉挛。"}},{"en":"a unit for measuring the speed of boats and aircraft; one nautical mile per hour","cn":"节（船和航空器的速度计量单位，每小时一海里）","sc":"speed of boat/plane"},{"en":"to fasten something with a knot or knots","cn":"把…打成结（或扎牢）","g":"[transitive]","sc":"tie with knot","ex":{"en":"He carefully knotted his tie.","cn":"他仔细地打着领带。"},"pos":"verb"},{"en":"to become twisted into a knot","cn":"缠结","g":"[intransitive]","sc":"bend into knot","pos":"verb"},{"en":"to twist hair into a particular shape","cn":"打发髻","g":"[transitive]","sc":"bend into knot","ex":{"en":"She wore her hair loosely knotted on top of her head.","cn":"她在头顶上打了个松松的发髻。"},"pos":"verb"},{"en":"if muscles, etc. knot or something knots them, they become hard and painful because of fear, excitement, etc.","cn":"（因害怕、激动等而）痉挛，紧缩，使痉挛","g":"[intransitive, transitive]","sc":"muscles","ex":{"en":"She felt her stomach knot with fear.","cn":"她十分害怕，感觉胃在抽搐。"},"pos":"verb"}]}},"kiss":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"吻；亲吻","en":"If you kiss someone, you touch them with your lips to show affection or sexual desire, or to greet them or say goodbye.","ex":{"en":"She leaned up and kissed him on the cheek","cn":"她倾身向前亲吻了他的面颊。"}},{"pos":"VERB 动词","cn":"轻吻（以示尊敬）","en":"If you kiss something, you touch it lightly with your lips, usually as a sign of respect.","ex":{"en":"The men stepped forward to kiss the hand of their mentor","cn":"这些男子走上前去轻吻他们导师的手。"}},{"pos":"VERB 动词","cn":"轻拂；轻触","en":"If you say that something kisses another thing, you mean that it touches that thing very gently.","ex":{"en":"The wheels of the aircraft kissed the runway.","cn":"飞机的轮子轻触跑道。"}},{"pos":"PHRASE 短语","cn":"飞吻","en":"If you blow someone a kiss or blow a kiss, you touch the palm of your hand lightly with your lips, and then blow across your hand towards the person, in order to show them your affection.","ex":{"en":"Maria blew him a kiss","cn":"玛丽亚给了他一个飞吻。"}},{"pos":"PHRASE 短语","cn":"任其失去；放弃；承认对…无能为力","en":"If you say that you kiss something goodbye or kiss goodbye to something, you accept the fact that you are going to lose it, although you do not want to.","ex":{"en":"I felt sure I'd have to kiss my dancing career goodbye.","cn":"我明确感觉到我将不得不与我的舞蹈生涯说再见了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to touch someone with your lips, usually on their lips or cheek, as a sign of love or as a greeting","cn":""},{"en":"to kiss someone once, as a sign of love or as a greeting","cn":""},{"en":"to give someone a small, quick kiss on their cheek, often in a way that is slightly formal","cn":""}]},"collocations":{"phrases":["ADJ. brief, quick, swift | lingering, long | gentle, light, soft | big, smacking | hard | sloppy | affectionate, loving, tender, warm | arde","VERB + KISS give sb He gave his daughter a gentle kiss on the forehead. | drop, plant, press She planted a big kiss on his cheek. | steal Th","KISS + VERB deepen His kiss deepened and became hungrier.","PREP. with a ~ | ~ on He greeted her with a kiss on the cheek.","PHRASES give sb the kiss of life A policeman pulled the man out of the river and gave him the kiss of life. | hugs and kisses We were greete"]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdekiss.mp3","us":"media/ldoce/hwd/ame/4/kiss1.mp3"},"examples":[{"en":"We were greeted with hugs and kisses.","cn":"我们受到欢迎，又是拥抱，又是亲吻。"},{"en":"The sunlight kissed the warm stones.","cn":"阳光洒落在温暖的石块上。"}],"oxford":{"phon":"kɪs","pos":"verb","senses":[{"en":"to touch somebody with your lips as a sign of love or sexual desire or when saying hello or goodbye","cn":"亲吻；接吻","g":"[intransitive, transitive]","ex":{"en":"They stood in a doorway kissing (= kissing each other).","cn":"他们站在门口亲吻。"}},{"en":"to gently move or touch something","cn":"轻拂；轻触","g":"[transitive]","lab":"literary","ex":{"en":"The sunlight kissed the warm stones.","cn":"阳光洒落在温暖的石块上。"}},{"en":"the act of kissing somebody/something","cn":"吻","ex":{"en":"Come here and give me a kiss!","cn":"过来亲亲我吧！"},"pos":"noun"},{"en":"a US heavy metal band which formed in 1972. Members of the band painted their faces, coloured their hair and performed in a wild way on stage. This included destroying guitars, breathing fire and letting false blood come from their mouths. Their albums have included KISS (1974), Unmasked (1980) and Carnival of Souls (1997).","cn":"一支成立于1972年的美国重金属乐队。乐队成员为自己的脸庞上色，染发，并在舞台上狂野地表演。这包括销毁吉他，吐火并让嘴里冒出鲜血。他们的专辑包括KISS（1974），Unmasked（1980）和Carnival of Souls（1997）。","pos":""}]}},"knighthood":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（英国国王或女王授予的）爵士头衔，骑士头衔，爵士称号，骑士称号（其名前冠以Sir）","en":"A knighthood is a title that is given to a man by a British king or queen for his achievements or his service to his country. A man who has been given a knighthood can put 'Sir' in front of his name instead of 'Mr'."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a British rank and title that are given to a man as an honour for achievement or for doing good things 〔","cn":"英国的〕爵士封号[头衔]"}]},"collocations":{"phrases":["ADJ. honorary","VERB + KNIGHTHOOD get, receive | refuse | award sb, bestow on sb, confer on sb, give sb, offer sb, reward sb with He was rewarded with a kni"]},"media":{"uk":"media/ldoce/hwd/bre/c/knighthood0205.mp3","us":"media/ldoce/hwd/ame/1/knighthood.mp3"},"examples":[{"en":"He received a knighthood in the New Year's Honours list.","cn":"他是新年受勋者之一，荣获爵士称号。"}],"oxford":{"phon":"ˈnaɪthʊd","pos":"noun","senses":[{"en":"(in the UK) the rank or title of a knight","cn":"（英国）爵士头衔，骑士头衔，爵士称号，骑士称号","ex":{"en":"He received a knighthood in the New Year's Honours list.","cn":"他是新年受勋者之一，荣获爵士称号。"}}]}},"kid":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小孩","en":"You can refer to a child as a kid .","ex":{"en":"They've got three kids","cn":"他们有3个孩子。"}},{"pos":"N-COUNT; N-VOC 可数名词；称呼名词","cn":"青少年","en":"Young people who are no longer children are sometimes referred to as kids .","ex":{"en":"There were gangs of kids on motorbikes roaming around","cn":"过去有成群结队的年轻人骑着摩托车四处游荡。"}},{"pos":"ADJ 形容词","cn":"年幼的","en":"You can refer to your younger brother as your kid brother and your younger sister as your kid sister.","ex":{"en":"My kid sister woke up and started crying.","cn":"我妹妹醒了，哭了起来。"}},{"pos":"N-COUNT 可数名词","cn":"小山羊","en":"A kid is a young goat."},{"pos":"VERB 动词","cn":"开玩笑","en":"If you are kidding, you are saying something that is not really true, as a joke.","ex":{"en":"I'm not kidding, Frank. There's a cow out there, just standing around","cn":"我没有开玩笑，弗兰克。外面有一头母牛，就站在附近。"}},{"pos":"VERB 动词","cn":"戏弄；逗惹","en":"If you kid someone, you tease them.","ex":{"en":"He liked to kid Ingrid a lot","cn":"他很喜欢捉弄英格丽德。"}},{"pos":"VERB 动词","cn":"欺骗；哄骗","en":"If people kid themselves, they allow themselves to believe something that is not true because they wish that it was true.","ex":{"en":"We're kidding ourselves, Bill. We're not winning, we're not even doing well","cn":"我们在自己骗自己，比尔。我们没有赢，我们甚至都没有发挥好。"}},{"pos":"CONVENTION 惯用语","cn":"（强调所说的是真实的或是认真的）真的，不是开玩笑","en":"You can say 'No kidding' to emphasize that what you are saying is true, or that you mean it.","ex":{"en":"I'm scared. No kidding, really.","cn":"我很害怕。不是开玩笑，真的。"}},{"pos":"CONVENTION 惯用语","cn":"（表示感兴趣或惊讶）真的吗？","en":"You can say 'No kidding?' to show that you are interested or surprised when someone tells you something.","ex":{"en":"'We won.' — 'No kidding?'","cn":"“我们赢了。”——“真的吗？”"}},{"pos":"PHRASE 短语","cn":"（表示认为某人所言极为荒唐或完全是假的）你一定是在开玩笑","en":"You can say 'you've got to be kidding' or 'you must be kidding' to someone if they have said something that you think is ridiculous or completely untrue.","ex":{"en":"You've got to be kidding! I can't live here!","cn":"你在开玩笑吧！我不可能住这儿！"}},{"pos":"PHRASE 短语","cn":"（表示认为某人不够真诚或不相信某人所言）她骗谁啊？/他想骗谁啊?","en":"You can say 'who is she kidding?' or 'who is he trying to kid?' if you think it is obvious that someone is not being sincere and does not mean what they say.","ex":{"en":"She played the role of a meek, innocent, shy girl. I don't know who she was trying to kid","cn":"她装作一个温顺、天真、害羞的女孩。真不知道她想骗谁。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is not yet an adult. You don’t usually use child to talk about babies or teenagers","cn":""},{"en":"a child. Kid is the usual word to use in everyday spoken English","cn":""},{"en":"a young male or female child","cn":""}]},"vocab":{"pos":"1 n 2 n 3 v","senses":[{"en":"If a farmer offers to introduce you to her kid , you might not know if she means her child or her baby goat."}]},"collocations":{"phrases":["ADJ. little, young | big, older The older kids had lessons in the afternoon as well. | cute, good, lovely, nice | poor I feel desperately so","QUANT. bunch, couple They're just a bunch of kids.","VERB + KID have We both wanted to have kids. | bring up I've tried to bring my kids up to respect other people. | look after, take care of","PHRASES just/only a kid He's only a kid. You can't expect him to understand what's going on. | like a kid She was crying like a kid."]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdekid.mp3","us":"media/ldoce/hwd/ame/d/kid1.mp3"},"examples":[{"en":"I thought he was kidding when he said he was going out with a rock star.","cn":"他说他在与一位摇滚乐歌星谈恋爱，我还以为他在开玩笑呢。"},{"en":"They're kidding themselves if they think it's going to be easy.","cn":"如果他们认为这会很容易，那是自己欺骗自己。"}],"oxford":{"phon":"kɪd","pos":"noun","senses":[{"en":"a child or young person","cn":"小孩；年轻人","g":"[countable]","lab":"informal","ex":{"en":"Do you have any kids?","cn":"你有孩子吗？"}},{"en":"a young goat","cn":"小山羊","g":"[countable]"},{"en":"soft leather made from the skin of a young goat","cn":"小山羊皮革","g":"[uncountable]","ex":{"en":"a pair of white kid gloves","cn":"一双白色小羊皮手套"}},{"en":"to tell somebody something that is not true, especially as a joke","cn":"戏弄；开玩笑","g":"[intransitive, transitive]","ex":{"en":"I thought he was kidding when he said he was going out with a rock star.","cn":"他说他在与一个摇滚明星谈恋爱，我还以为他在开玩笑呢。"},"pos":"verb"},{"en":"to allow somebody/yourself to believe something that is not true","cn":"欺骗；哄骗","g":"[transitive]","ex":{"en":"They're kidding themselves if they think it's going to be easy.","cn":"如果他们认为这会很容易，那是自己欺骗自己。"},"pos":"verb"},{"en":"a person’s younger sister/brother","cn":"妹妹；弟弟","pos":"adjective"}]}},"kudos":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（因行为或成就而获得的）荣誉，赞誉，名声","en":"Kudos is admiration or recognition that someone or something gets as a result of a particular action or achievement.","ex":{"en":"...a new hotel chain that has won kudos for the way it treats guests.","cn":"因其待客方式受到好评的新的连锁酒店"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of being admired and respected for being important or for doing something important","cn":"荣誉﹐光荣﹔名声"}]},"vocab":{"pos":"n","senses":[{"en":"If you're really good at judo, you will get kudos , or praise and congratulations, for your speed and strength."}]},"collocations":{"phrases":["ADJ. considerable | personal","VERB + KUDOS acquire, gain | lose | bring Employees enjoy the kudos that the job brings as much as the financial rewards.","KUDOS + VERB be attached to sth There was considerable kudos attached to being on the advisory board."]},"media":{"uk":"media/ldoce/hwd/bre/9/kudos0205.mp3","us":"media/ldoce/hwd/ame/e/kudos.mp3"},"examples":[{"en":"the kudos of playing for such a famous team","cn":"跟着这样著名的队参加比赛的荣誉"},{"en":"He acquired kudos just by appearing on television.","cn":"他上电视后就出名了。"}],"oxford":{"phon":"ˈkjuːdɒs","pos":"noun","senses":[{"en":"the praise and honour that goes with a particular achievement or position","cn":"（随某成就或地位而来的）荣誉，威信，名声","ex":{"en":"the kudos of playing for such a famous team","cn":"能为这样的名队效力的荣誉"}},{"en":"special praise to somebody for something they have done","cn":"（因做了某事而获得的）特殊荣誉，特别表彰","lab":"informal","ex":{"en":"Kudos to Bill for fixing that problem.","cn":"比尔解决了那个问题，向他致敬。"}}]}},"kyrgyzstan":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in central Asia between China and Uzbekistan, which used to be part of the former Soviet Union. Population: 5,548,042 (2014). Capital: Bishkek.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/p028-000007103.mp3","us":"media/ldoce/hwd/ame/b/p028-000007103.mp3"},"oxford":{"phon":"ˌkɜːɡɪˈstɑːn","pos":"noun","senses":[{"en":"a country in Central Asia","cn":"吉尔吉斯斯坦（中亚国家）"}]}},"kit":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"成套工具；成套设备","en":"A kit is a group of items that are kept together, often in the same container, because they are all used for similar purposes.","ex":{"en":"...a well-stocked first aid kit","cn":"一套完备的急救用品"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指某运动的）全套衣服和装备","en":"Kit is special clothing and equipment that you use when you take part in a particular activity, especially a sport.","ex":{"en":"I forgot my gym kit.","cn":"我忘带健身用品了。"}},{"pos":"N-COUNT 可数名词","cn":"配套元件","en":"A kit is a set of parts that can be put together in order to make something.","ex":{"en":"Her popular pot holder is also available in do-it-yourself kits.","cn":"她那广受欢迎的防烫布垫也可以自己购买原料套装自己制作。"}},{"pos":"PHRASE 短语","cn":"脱掉所有衣服/不脱掉所有衣服","en":"If someone gets their kit off or takes their kit off, they take off all their clothes. If they keep their kit on, they do not take off all their clothes, even though people may be expecting them to.","ex":{"en":"I don't like taking my kit off on screen","cn":"我不喜欢在银幕上表演裸戏。"}},{"pos":"","cn":"","en":"相关词组：kit out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the machines, tools, or objects that you use for doing something","cn":""},{"en":"equipment and clothes for an activity that you do in your spare time","cn":""},{"en":"things for a particular purpose or activity, especially ones kept together in their own container","cn":""}]},"collocations":{"phrases":["ADJ. combat, football, sports | first-aid, repair, sewing, shaving, survival, test, tool Check the acidity of the soil with a test kit.","PREP. in a/the ~ There should be a needle and thread in the sewing kit. 2 set of parts","ADJ. construction","VERB + KIT make up Have you made up the kit yet?","KIT + VERB comprise sth, contain sth, include sth The kit contains everything you need to make six candles.","PREP. from a ~ They built the garage from a kit. | ~ for a kit for making candles","PHRASES in kit form The doll's house comes in kit form."]},"media":{"uk":"media/ldoce/hwd/bre/d/kit_n0205.mp3","us":"media/ldoce/hwd/ame/1/kit.mp3"},"examples":[{"en":"They were all kitted out in brand-new ski outfits.","cn":"他们都一身全新的滑雪装备。"},{"en":"a kit for a model plane","cn":"一套飞机模型元件"}],"oxford":{"phon":"kɪt","pos":"noun","senses":[{"en":"a set of tools or equipment that you use for a particular purpose","cn":"成套工具；成套设备","g":"[countable, uncountable]","ex":{"en":"a drum kit","cn":"一套击鼓用具"}},{"en":"a set of parts ready to be made into something","cn":"配套元件","g":"[countable]","ex":{"en":"a kit for a model plane","cn":"一套飞机模型元件"}},{"en":"a set of clothes and equipment that you use for a particular activity","cn":"全套衣服及装备","g":"[uncountable]","lab":"British English","ex":{"en":"sports kit","cn":"运动用品"}},{"en":"a first name for boys, short for Christopher","cn":"基特（男子名，Christopher 缩写）","pos":""}]}},"karate":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"空手道","en":"Karate is a Japanese sport or way of fighting in which people fight using their hands, elbows, feet, and legs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a Japanese fighting sport, in which you use your feet and hands to hit and kick","cn":"空手道〔一种日本武术〕"}]},"collocations":{"phrases":["ADJ. full-contact","VERB + KARATE do","KARATE + NOUN stance | jacket, suit | blow, chop, kick, punch | bout, competition, tournament | training | champion, expert | instructor","PHRASES a black, etc. belt in karate She's a black belt in karate. She's got a brown belt in karate. •"]},"media":{"uk":"media/ldoce/hwd/bre/3/karate0205.mp3","us":"media/ldoce/hwd/ame/1/karate.mp3"},"examples":[{"en":"a karate chop (= a blow with the side of the hand)","cn":"空手道的掌侧劈"}],"oxford":{"phon":"kəˈrɑːti","pos":"noun","senses":[{"en":"a Japanese system of fighting in which you use your hands and feet as weapons","cn":"空手道","ex":{"en":"a karate chop (= a blow with the side of the hand)","cn":"空手道的掌侧劈"}}]}},"klondike":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"an area in northwest Canada, in the Yukon. Gold was discovered there in the 1890s, and this caused a gold rush (= when many people go to an area to look for gold ) . If a lot of people hurry to a particular place to do an activity, the situation is sometimes s","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/p028-000007038.mp3","us":"media/ldoce/hwd/ame/6/p028-000007038.mp3"}},"knead":{"collins":{"senses":[{"pos":"VERB 动词","cn":"揉，捏（面团或其他食物）","en":"When you knead dough or other food, you press and squeeze it with your hands so that it becomes smooth and ready to cook.","ex":{"en":"Lightly knead the mixture on a floured surface.","cn":"在撒上面粉的台面上轻揉该混合物。"}},{"pos":"VERB 动词","cn":"揉捏；按摩；推拿","en":"If you knead a part of someone's body, you press or squeeze it with your fingers.","ex":{"en":"She felt him knead the aching muscles.","cn":"她感到他在按摩她酸痛的肌肉。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to push something firmly with your fingers or with your feet. In American English push is usually used to describe what you do to buttons, bells etc","cn":""},{"en":"to push something firmly inwards by pressing on both sides of it, especially with your hands or fingers","cn":""},{"en":"to press someone's skin tightly between your fingers and thumb, so that it hurts","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To knead is to massage, as you might knead a sore muscle to relieve the pain or knead bread dough before baking it."}]},"collocations":{"phrases":["ADV. gently, lightly She gently kneaded the muscles in his back. | well Add the water and knead the mixture well."]},"media":{"uk":"media/ldoce/hwd/bre/9/knead0205.mp3","us":"media/ldoce/hwd/ame/4/knead.mp3","img":["media/thumb/knead.jpg"]},"examples":[{"en":"Knead the dough for three minutes.","cn":"将面团揉三分钟。"}],"oxford":{"phon":"niːd","pos":"verb","senses":[{"en":"to press and stretch dough, wet clay, etc. with your hands to make it ready to use","cn":"揉，捏（面团、湿黏土等）","ex":{"en":"Add the water and knead the mixture well.","cn":"加水后把混合料揉好。"}},{"en":"to rub and press muscles, etc. especially to relax them or to make them less painful","cn":"揉捏，按摩，推拿（肌肉等）","ex":{"en":"She gently kneaded the muscles in his back.","cn":"她轻轻地给他按摩后背。"}}]}},"kazakhstan":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in central Asia, between Russia and China, which was part of the former Soviet Union, and is now an independent country. Population: 17,736,896 (2014). Capital: Astana.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/p028-000006884.mp3","us":"media/ldoce/hwd/ame/c/p028-000006884.mp3"},"oxford":{"phon":"ˌkæzəkˈstɑːn","pos":"noun","senses":[{"en":"a country in Central Asia","cn":"哈萨克斯坦（中亚国家）"}]}},"knack":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"诀窍；本领","en":"A knack is a particularly clever or skilful way of doing something successfully, especially something which most people find difficult.","ex":{"en":"He's got the knack of getting people to listen.","cn":"他有使人倾听的本领。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to do something well especially because you have learned and practised it","cn":""},{"en":"the ability to do something well, either because you have learned how to do it or because you are naturally good at it","cn":""},{"en":"a natural ability to do something very well","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you have a knack for doing something, you do it well. You may have a knack for baking cakes or a knack for cracking jokes. These things come easy to you."}]},"collocations":{"phrases":["ADJ. happy | uncanny | unhappy He had the unhappy knack of making enemies in the party.","VERB + KNACK have | acquire, develop, get Once you get the knack, it's easy. | lose I don't cook much these days and I think I may have lost","PREP. ~ for a woman with a knack for handling horses | ~ of He has the knack of scoring goals just when they are most needed. | ~ to Making "]},"media":{"uk":"media/ldoce/hwd/bre/b/knack0205.mp3","us":"media/ldoce/hwd/ame/2/knack.mp3"},"examples":[{"en":"It's easy, once you've got the knack.","cn":"你一旦掌握这个技能就容易了。"},{"en":"She has the unfortunate knack of always saying the wrong thing.","cn":"不幸的是，她总是说错话。"}],"oxford":{"phon":"næk","pos":"noun","senses":[{"en":"a special skill or ability that you have naturally or can learn","cn":"技能；本领","ex":{"en":"It's easy, once you've got the knack.","cn":"你一旦掌握这个技能就容易了。"}},{"en":"a habit of doing something","cn":"习惯；癖好","ex":{"en":"She has the unfortunate knack of always saying the wrong thing.","cn":"不幸的是，她总是说错话。"}}]}},"knuckle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"指节；指关节","en":"Your knuckles are the rounded pieces of bone that form lumps on your hands where your fingers join your hands, and where your fingers bend. a rap on the knuckles→see: ;","ex":{"en":"Brenda's knuckles were white as she gripped the arms of the chair.","cn":"布伦达握紧椅子扶手时指关节都变白了。"}},{"pos":"","cn":"","en":"相关词组：knuckle down knuckle under"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"your knuckles are the joints in your fingers, including the ones where your fingers join your hands","cn":"指节﹔指关节"},{"en":"a piece of meat around the lowest leg joint of a pig 〔","cn":"猪的〕肘"},{"en":"rude, or likely to give offence","cn":"粗鲁的﹔近乎下流的"}]},"collocations":{"phrases":["ADJ. bony | bleeding, bloodied, bruised, grazed, swollen","VERB + KNUCKLE crack He rubbed his hands together, cracking his knuckles as he tried to control his anger. | bruise, graze, scrape, skin","KNUCKLE + NOUN bone","PHRASES rap sb on/over the knuckles (figurative) The Assistant Manager was rapped over the knuckles for criticizing the company in the press"]},"media":{"uk":"media/ldoce/hwd/bre/d/knuckle_n0205.mp3","us":"media/ldoce/hwd/ame/6/knuckle1.mp3"},"examples":[{"en":"I'm going to have to knuckle down to some serious study.","cn":"我得开始认认真真地学习了。"},{"en":"Her knuckles whitened as she gripped the gun.","cn":"她紧紧握着枪﹐指关节都发白了。"}],"oxford":{"phon":"ˈnʌkl","pos":"noun","senses":[{"en":"any of the joints in the fingers, especially those connecting the fingers to the rest of the hand","cn":"指节；指关节","g":"[countable]","ex":{"en":"She clenched the phone till her knuckles were white.","cn":"她紧握电话，连指关节都变白了。"}},{"en":"a piece of meat from the lower part of an animal’s leg, especially a pig","cn":"（猪等动物的）肘，蹄","g":"[uncountable, countable]","ex":{"en":"knuckle of pork","cn":"猪蹄"}}]}},"kerb":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"路缘；道牙；马路牙子","en":"The kerb is the raised edge of a pavement or sidewalk which separates it from the road.","ex":{"en":"Stewart stepped off the kerb.","cn":"斯图尔特走下马路牙子。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of something that is furthest from its centre or nearest the place where it ends","cn":""},{"en":"the part of something that is near its left or right edge","cn":""},{"en":"the edge of something circular, especially the top of a cup or glass, or the outside edge of a pair of glasses","cn":""}]},"collocations":{"phrases":["ADJ. dropped Dropped kerbs make wheelchair access easier.","VERB + KERB draw away from, pull away/out from The car pulled away from the kerb. | draw up at/to, pull in/over to | step off He stepped off","PREP. at the ~ I parked at the kerb and waited. | on the ~ They stood on the kerb waiting to cross the road."]},"media":{"uk":"media/ldoce/hwd/bre/0/kerb_las2_br.mp3","us":"media/ldoce/hwd/ame/7/laadkerb.mp3"},"examples":[{"en":"The bus mounted the kerb (= went onto the pavement / sidewalk ) and hit a tree.","cn":"那辆公共汽车开上路缘撞到了一棵树。"},{"en":"His car mounted the kerb and ploughed into a bus queue.","cn":"他的汽车冲上路缘﹐撞到了排队等候公共汽车的人。"}],"oxford":{"phon":"kɜːb","pos":"noun","senses":[{"en":"the edge of the raised path at the side of a road, usually made of long pieces of stone","cn":"（由条石砌成的）路缘；道牙；马路牙子","ex":{"en":"The bus mounted the kerb (= went onto the pavement) and hit a tree.","cn":"公共汽车开上路缘撞到了一棵树。"}}]}},"killer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"杀人者；杀手","en":"A killer is a person who has killed someone, or who intends to kill someone.","ex":{"en":"The police are searching for his killers","cn":"警方正在搜捕杀害他的凶手。"}},{"pos":"N-COUNT 可数名词","cn":"导致死亡的事物","en":"You can refer to something that causes death or is likely to cause death as a killer .","ex":{"en":"Heart disease is the biggest killer of men in most developed countries.","cn":"在多数发达国家，心脏病是导致人们死亡的头号杀手。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has deliberately killed another person","cn":""},{"en":"someone who deliberately kills someone else - used especially in newspapers","cn":""},{"en":"someone who kills a famous or important person, sometimes because someone else has paid them to do it","cn":""}]},"collocations":{"phrases":["ADJ. big, major Overdoses were the single biggest killer among the city's young. | real I don't care what they ask me if it helps them find ","VERB + KILLER hunt, track down | catch, find","KILLER + VERB strike The killer has struck again.","KILLER + NOUN bug, disease, virus Heart attacks have become Britain's No. 1 killer disease. | instinct (figurative) He plays well but still "]},"media":{"uk":"media/ldoce/hwd/bre/d/killer_las2_br.mp3","us":"media/ldoce/hwd/ame/9/killer.mp3"},"examples":[{"en":"Police are hunting his killer.","cn":"警方正在追捕杀害他的凶手。"},{"en":"Heart disease is the biggest killer in Scotland.","cn":"心脏病是苏格兰的头号杀手。"}],"oxford":{"phon":"ˈkɪlə(r)","pos":"noun","senses":[{"en":"a person, an animal or a thing that kills","cn":"杀人者；杀手；导致死亡的人（或动物、事物）","ex":{"en":"Police are hunting his killer.","cn":"警方正在追捕杀害他的凶手。"}},{"en":"something that is very difficult, very exciting or shows a lot of skill","cn":"棘手的事；令人激动的事物；精彩的事物","lab":"informal","ex":{"en":"The exam was a real killer.","cn":"这考试可真费劲。"}}]}},"knight":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（中世纪的）骑士","en":"In medieval times, a knight was a man of noble birth, who served his king or lord in battle."},{"pos":"VERB 动词","cn":"封…为爵士","en":"If someone is knighted, they are given a knighthood.","ex":{"en":"He was knighted in the Queen's birthday honours list in June 1988.","cn":"他于1988年6月被封为爵士，是女王生日宴会上的受勋者之一。"}},{"pos":"N-COUNT 可数名词","cn":"爵士","en":"A knight is a man who has been knighted."},{"pos":"N-COUNT 可数名词","cn":"（国际象棋中的）马","en":"In chess, a knight is a piece which is shaped like a horse's head."},{"pos":"PHRASE 短语","cn":"救人于危难之中的勇士","en":"If you refer to someone as a knight in shining armour, you mean that they are kind and brave, and likely to rescue you from a difficult situation.","ex":{"en":"Love songs trick us into believing in knights in shining armor.","cn":"情歌哄骗我们去相信有勇救美人的英雄。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man with a high rank in the past who was trained to fight while riding a horse","cn":"骑士﹐武士"},{"en":"a man who has received a knighthood and has the title sir before his name","cn":"爵士〔名前冠有Sir这一头衔〕"},{"en":"the chess piece with a horse’s head on it 〔","cn":"国际象棋中的〕马"}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Traditionally the noun knight means someone born of the nobility and trained to fight, usually in heavy metal armor. As a verb, if a king decides to knight you, that means the king wants to make you into a knight ."}]},"collocations":{"phrases":["ADJ. medieval | chivalrous, noble | armoured | mounted","PHRASES a knight errant tales of medieval knights errant, wandering in search of chivalrous adventures | a knight in armour, a knight in shi"]},"media":{"uk":"media/ldoce/hwd/bre/9/knight_n0205.mp3","us":"media/ldoce/hwd/ame/f/knight1.mp3"},"examples":[{"en":"He was knighted by the Queen for his services to industry.","cn":"他因对工业界的贡献获女王封为爵士。"},{"en":"knights in armour","cn":"身披盔甲的骑士"}],"oxford":{"phon":"naɪt","pos":"noun","senses":[{"en":"(in the Middle Ages) a man of high social rank who had a duty to fight for his king. Knights are often shown in pictures riding horses and wearing armour.","cn":"（中世纪的）骑士","ex":{"en":"tales of medieval knights errant, wandering in search of chivalrous adventures","cn":"中世纪游侠到处历险的故事"}},{"en":"(in the UK) a man who has been given a special honour by the king or queen and has the title Sir before his name","cn":"（英国）爵士（其名前冠以 Sir）"},{"en":"a piece used in the game of chess that is like a horse’s head in shape","cn":"（国际象棋中的）马"},{"en":"to give somebody the rank and title of a knight","cn":"封（某人）为爵士","ex":{"en":"He was knighted by the Queen for his services to industry.","cn":"他因对工业界的贡献获女王封为爵士。"},"pos":"verb"}]}},"kathmandu":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the capital city of Nepal, in the Himalayas","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/p028-000006880.mp3","us":"media/ldoce/hwd/ame/0/laadkathmandu.mp3"}},"kosher":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（尤指食物）合礼的（合乎犹太教教规的）","en":"Something, especially food, that is kosher is approved of or allowed by the laws of Judaism.","ex":{"en":"...a kosher butcher.","cn":"合礼的屠户"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合适的；正确的","en":"Something that is kosher is generally approved of or considered to be correct.","ex":{"en":"I guessed something wasn't quite kosher","cn":"我觉得有点不对劲儿。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"kosher food is prepared according to Jewish law 〔","cn":"食品〕按犹太教规制成的"},{"en":"kosher restaurants or shops sell food prepared in this way 〔","cn":"餐馆或商店〕供应符合犹太教规食物的"},{"en":"something that is kosher is honest, legal, or really what it is claimed to be","cn":"诚实可靠的﹔合法的﹔真实的"}]},"vocab":{"pos":"adj n","senses":[{"en":"In Jewish law, food must be ritually cleaned and prepared in order to be kosher , or fit to eat. Today, it can also mean anything that is proper or legitimate. Is it kosher to date your best friend's ex? Depends on who you ask."}]},"collocations":{"phrases":["VERBS be","ADV. strictly All their food is strictly kosher. 2 correct/honest","VERBS be, seem It all seems kosher enough.","ADV. strictly | enough"]},"media":{"uk":"media/ldoce/hwd/bre/e/kosher0205.mp3","us":"media/ldoce/hwd/ame/c/kosher.mp3"},"examples":[{"en":"Their business deals are not always completely kosher.","cn":"他们的商业活动并不总是光明正大的。"},{"en":"Are you sure this offer is kosher?","cn":"你肯定这个报价是实价吗？"}],"oxford":{"phon":"ˈkəʊʃə(r)","pos":"adjective","senses":[{"en":"prepared according to the rules of Jewish law","cn":"合礼的（合乎犹太教教规及礼仪要求的）","ex":{"en":"a kosher meal","cn":"犹太餐"}},{"en":"honest or legal","cn":"诚实的；合法的","lab":"informal","ex":{"en":"Their business deals are not always completely kosher.","cn":"他们的商业活动并不总是光明正大的。"}}]}},"kin":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"（统称）家属，亲属，亲戚","en":"Your kin are your relatives.","ex":{"en":"She has gone to live with her husband's kin.","cn":"她住到丈夫的亲戚家里去了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"your family","cn":"家人﹐家属﹐亲属"},{"en":"your most closely related family","cn":"最近的亲属﹐直系亲属"}]},"vocab":{"pos":"n adj","senses":[{"en":"Some say kin, others \"family,\" or \"relatives.\" Call them what you will, but you’re stuck with those people related to you by blood or marriage."}]},"collocations":{"phrases":["ADJ. close, intimate, near Marriage between close kin is prohibited. | extended Ties with extended kin vary from family to family. | distant","KIN + NOUN group, network | relationships","PREP. between ~","PHRASES next of kin One of the drivers was fatally injured; his next of kin has been informed."]},"media":{"uk":"media/ldoce/hwd/bre/e/kin0205.mp3","us":"media/ldoce/hwd/ame/2/kin.mp3"},"examples":[{"en":"We’ll have to notify the next of kin of his death.","cn":"我们得把他去世的消息通知他的直系亲属。"}],"oxford":{"phon":"kɪn","pos":"noun","senses":[{"en":"your family or your relatives","cn":"（统称）家属，亲属，亲戚","ex":{"en":"Marriage between close kin is prohibited.","cn":"禁止近亲结婚。"}}]}},"kip":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"睡觉","en":"Kip is sleep.","ex":{"en":"Mason went home for a couple of hours' kip.","cn":"梅森回家睡了几个小时。"}},{"pos":"VERB 动词","cn":"（通常指不是在自己家或床上）睡觉","en":"If you kip somewhere, usually somewhere that is not your own home or bed, you sleep there.","ex":{"en":"He moved from one friend's flat to another, first kipping on the floor of Theodore's studio.","cn":"他从一个朋友的公寓搬到另一个朋友处，最初是睡在西奥多工作室的地板上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the time when you are sleeping","cn":""},{"en":"to be sleeping","cn":""},{"en":"to sleep after a period of time when you have not been able to sleep because of illness, worry, work etc","cn":""}]},"collocations":{"phrases":["VERB + KIP catch, get, have Try to catch some kip while you can. | need","PHRASES an hour's, a night's, etc. kip I was feeling much better after a good night's kip."]},"media":{"uk":"media/ldoce/hwd/bre/3/kip_n0205.mp3","us":"media/ldoce/hwd/ame/f/ld41kip.mp3"},"examples":[{"en":"Why don't you have a quick kip?","cn":"你为什么不小睡一会儿呢？"},{"en":"You can kip on the sofa, if you like.","cn":"你想睡可以睡在沙发上。"}],"oxford":{"phon":"kɪp","pos":"noun","senses":[{"en":"sleep","cn":"睡觉","ex":{"en":"I must get some kip.","cn":"我得睡会儿觉。"}},{"en":"to sleep","cn":"睡；睡眠","ex":{"en":"You can kip on the sofa, if you like.","cn":"你想睡可以睡在沙发上。"},"pos":"verb"}]}},"knickers":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"女士短衬裤","en":"Knickers are a piece of underwear worn by women and girls which have holes for the legs and elastic around the waist to hold them up.","ex":{"en":"She bought Ann two bras and six pairs of knickers.","cn":"她给安买了两件胸罩、6条内裤。"}},{"pos":"PHRASE 短语","cn":"恼火；烦闷","en":"If someone is getting their knickers in a twist about something, they are getting annoyed or upset about it without good reason.","ex":{"en":"The company, which makes its money on 3,000 grocery lines has its knickers in a twist about Sunday trading.","cn":"这家依靠3,000种食品杂货盈利的公司为其星期天的营业状况烦恼。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of women’s underwear worn between the waist and the top of the legs","cn":"女用内裤"},{"en":"knickerbockers","cn":"灯笼裤"},{"en":"used to say that someone is upset, or to tell someone not to get upset (","cn":"别)感到不快﹐(不必)恼火"}]},"collocations":{"phrases":["ADJ. French","QUANT. pair","VERB + KNICKERS pull down/up","PHRASES bra and knickers •"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeknickers.mp3","us":"media/ldoce/hwd/ame/c/knickers.mp3"},"examples":[{"en":"knicker elastic （","cn":"女用）短衬裤松紧带"},{"en":"a pair of knickers","cn":"一条女式短衬裤"}],"oxford":{"phon":"ˈnɪkəz","pos":"noun","senses":[{"en":"a piece of women’s underwear that covers the body from the middle part to the tops of the legs","cn":"女式短衬裤","lab":"British English","ex":{"en":"a pair of knickers","cn":"一条女式短衬裤"}},{"en":"short loose trousers that fit tightly just below the knee, worn especially in the past","cn":"（尤指旧时穿的膝下扎紧的）灯笼裤","lab":"North American English"}]}},"kite":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"风筝","en":"A kite is an object, usually used as a toy, which is flown in the air. It consists of a light frame covered with paper or cloth and has a long string attached which you hold while the kite is flying."},{"pos":"N-COUNT 可数名词","cn":"鸢（一种猛禽）","en":"A kite is a bird of prey which hunts and kills small animals for food."},{"pos":"PHRASE 短语","cn":"试探舆论（或反应）","en":"If you say that someone is flying a kite, you are critical of them for putting forward new ideas just to see how people react, rather than with the intention of putting those ideas into practice.","ex":{"en":"The Government flies these kites of disinformation, then people feel grateful when the changes don't happen.","cn":"政府故意放出这些虚假消息来试探舆论，而当其中提到的改变并未出现时，老百姓便会心怀感激。"}},{"pos":"PHRASE 短语","cn":"极度兴奋的；被酒精（或毒品）麻醉的","en":"If you say that someone is as high as a kite, you mean that they are very excited or that they are greatly affected by alcohol or drugs.","ex":{"en":"I felt so strange on the steroid injections. I was as high as a kite some of the time.","cn":"注射类固醇后我感觉很奇特。我有时会极度兴奋。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a light frame covered in coloured paper or plastic that you let fly in the air on the end of one or two long strings","cn":"风筝"},{"en":"a type of hawk (= bird that eats small animals )","cn":"鸢"},{"en":"an illegal cheque","cn":"空头支票﹔非法支票"}]},"collocations":{"phrases":["ADJ. stunt John wants to fly his new stunt kite.","VERB + KITE fly","KITE + NOUN flying the joys of kite flying"]},"media":{"uk":"media/ldoce/hwd/bre/5/kite_v0205.mp3","us":"media/ldoce/hwd/ame/3/kite1.mp3","img":["media/thumb/kite.jpg"]},"examples":[{"en":"to kite checks","cn":"用支票诈骗"},{"en":"check kiting","cn":"支票作弊"}],"oxford":{"phon":"kaɪt","pos":"noun","senses":[{"en":"a toy made of a light frame covered with paper, cloth, etc., that you fly in the air at the end of one or more long strings","cn":"风筝","ex":{"en":"to fly a kite","cn":"放风筝"}},{"en":"a bird of prey (= a bird that kills other creatures for food) of the hawk family","cn":"鸢（猛禽）"},{"en":"to use an illegal check to obtain money; to dishonestly change the amount written on a check","cn":"使用（非法支票）骗钱；涂改（支票）","ex":{"en":"to kite checks","cn":"用支票诈骗"},"pos":"verb"}]}},"know-how":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指专业或实用的）技巧，技能","en":"Know-how is knowledge of the methods or techniques of doing something, especially something technical or practical.","ex":{"en":"He hasn't got the know-how to run a farm.","cn":"他没有经营农场的专业知识。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the facts and information that you have learned, and the understanding you have gained","cn":""},{"en":"special knowledge about how to do something, that you get through experience, training, or study","cn":""},{"en":"practical knowledge about how to do something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Know-how is the knowledge and skill needed to complete a task. Mechanics have a lot of know-how when it comes to cars."}]},"collocations":{"phrases":["ADJ. practical, technical VERB + KNOW-HOW have | acquire, get","PREP. ~ about to acquire a little know-how about the job | ~ for He doesn't have the technical know-how for this kind of job. | ~ in know-ho"]},"media":{"uk":"media/ldoce/hwd/bre/c/know_how0205.mp3","us":"media/ldoce/hwd/ame/f/know-how.mp3"},"examples":[{"en":"We need skilled workers and technical know-how.","cn":"我们需要熟练工人和专业技术知识。"},{"en":"those who have the know-how to exploit the technology to the fullest","cn":"那些知道如何将技术发挥到最大限度的人"}],"oxford":{"phon":"ˈnəʊ haʊ","pos":"noun","senses":[{"en":"knowledge of how to do something and experience in doing it","cn":"专门知识；技能；实际经验","ex":{"en":"We need skilled workers and technical know-how.","cn":"我们需要熟练工人和专业技术知识。"}}]}},"kiwi":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同kiwi fruit","en":"A kiwi is the same as a kiwi fruit ."},{"pos":"N-COUNT 可数名词","cn":"几维（新西兰鸟，不能飞）","en":"A kiwi is a type of bird that lives in New Zealand. Kiwis cannot fly."},{"pos":"N-COUNT 可数名词","cn":"新西兰人（可能具冒犯意味）","en":"People who come from New Zealand are sometimes referred to as Kiwis. This use could cause offence."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a New Zealand bird that cannot fly","cn":"鹬鸵﹐几维〔新西兰的一种不会飞翔的鸟〕"},{"en":"someone from New Zealand","cn":"新西兰人"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41kiwi.mp3","us":"media/ldoce/hwd/ame/9/kiwi.mp3","img":["media/ldoce/img/kiwi.jpg"]},"oxford":{"phon":"ˈkiːwi","pos":"noun","senses":[{"en":"a person from New Zealand","cn":"新西兰人","lab":"informal"},{"en":"a New Zealand bird with a long beak, short wings and no tail, that cannot fly","cn":"几维，鹬鸵，无翼鸟（产于新西兰，不能飞）"},{"en":"a small fruit with thin brown skin covered with small hairs, that is soft and green inside with black seeds","cn":"猕猴桃；奇异果"}]}}});
